(303395,33711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cours ici porte sur l''algèbre.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce cours ici porte sur l''algèbre.'::text),
(303398,33711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buradaki ... ders cebirle ilgili.'::text,'bu'::text,'bu'::text,'şu'::text,'Buradaki bu ders cebirle ilgili.'::text),
(303399,33711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az óra itt az algebráról szól.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez az óra itt az algebráról szól.'::text),
(303402,33712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen schreibt während der Stunde in ... Heft.'::text,'ihr'::text,'sein'::text,'sein'::text,'Das Mädchen schreibt während der Stunde in ihr Heft.'::text),
(303406,33712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчина пише в ... зошиті під час уроку.'::text,'своєму'::text,'своєму'::text,'своєму'::text,'Дівчина пише в своєму зошиті під час уроку.'::text),
(303405,33712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chica escribe en ... cuaderno durante la clase.'::text,'su'::text,'su'::text,'su'::text,'La chica escribe en su cuaderno durante la clase.'::text),
(303404,33712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fille écrit dans ... cahier pendant le cours.'::text,'son'::text,'son'::text,'son'::text,'La fille écrit dans son cahier pendant le cours.'::text),
(303407,33712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız ders sırasında ... defterine yazıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Kız ders sırasında onun defterine yazıyor.'::text),
(303408,33712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lány az óra alatt a ... ír.'::text,'füzetébe'::text,'füzetébe'::text,'füzetébe'::text,'A lány az óra alatt a füzetébe ír.'::text),
(303420,33714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Das ist Stunde Nummer ... des Tages, nicht eins!'::text,'fünf'::text,'fünfte'::text,'Fünfen'::text,'Albtraum! Das ist Stunde Nummer fünf des Tages, nicht eins!'::text),
(303424,33714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Це урок номер ... за день, а не один!'::text,'п''ять'::text,'п''ятий'::text,'п''ятірки'::text,'Жах! Це урок номер п''ять за день, а не один!'::text),
(303423,33714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Es la clase número ... del día, no la uno!'::text,'cinco'::text,'quinta'::text,'cinco'::text,'¡Pesadilla! ¡Es la clase número cinco del día, no la uno!'::text),
(303422,33714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! C''est le cours numéro ... de la journée, pas le un !'::text,'cinq'::text,'cinquième'::text,'cinq'::text,'Cauchemar ! C''est le cours numéro cinq de la journée, pas le un !'::text),
(303425,33714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bu günün ... numaralı dersi, bir değil!'::text,'beş'::text,'beşinci'::text,'beşler'::text,'Kâbus! Bu günün beş numaralı dersi, bir değil!'::text),
(303426,33714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Ez az ... számú óra ma, nem az egyes!'::text,'öt'::text,'ötödik'::text,'ötösök'::text,'Rémálom! Ez az öt számú óra ma, nem az egyes!'::text),
(303429,33715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Diese Stunde bringt zu viel ... für einen Tag!'::text,'Hausaufgaben'::text,'Hausaufgaben'::text,'eine Hausaufgabe'::text,'Katastrophe! Diese Stunde bringt zu viel Hausaufgaben für einen Tag!'::text),
(303433,33715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! На цьому уроці забагато ... як на один день!'::text,'домашнього завдання'::text,'домашнього завдання'::text,'домашнього завдання'::text,'Катастрофа! На цьому уроці забагато домашнього завдання як на один день!'::text),
(303432,33715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Esta clase tiene demasiados ... para un solo día!'::text,'deberes'::text,'deberes'::text,'un deber'::text,'¡Desastre! ¡Esta clase tiene demasiados deberes para un solo día!'::text),
(303431,33715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Ce cours donne beaucoup trop de ... pour une seule journée !'::text,'devoirs'::text,'devoirs'::text,'un devoir'::text,'Catastrophe ! Ce cours donne beaucoup trop de devoirs pour une seule journée !'::text),
(303434,33715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Bu derste bir gün için çok fazla ... var!'::text,'ödev'::text,'ödevler'::text,'bir ödev'::text,'Felaket! Bu derste bir gün için çok fazla ödev var!'::text),
(303435,33715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Ez az óra túl sok ... ad egy napra!'::text,'házi feladatot'::text,'házi feladatot'::text,'egy házi feladatot'::text,'Katasztrófa! Ez az óra túl sok házi feladatot ad egy napra!'::text),
(303447,33717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... in jeder Stunde zwei Papierkugeln da.'::text,'sind'::text,'ist'::text,'sein'::text,'Girl, angeblich sind in jeder Stunde zwei Papierkugeln da.'::text),
(303451,33717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, на кожному уроці ... дві паперові кульки.'::text,'є'::text,'є'::text,'бути'::text,'Подруго, кажуть, на кожному уроці є дві паперові кульки.'::text),
(303450,33717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... dos bolas de papel en cada clase.'::text,'hay'::text,'hay'::text,'hay'::text,'Tía, al parecer hay dos bolas de papel en cada clase.'::text),
(303449,33717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ... deux boulettes de papier à chaque cours.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Meuf, apparemment il y a deux boulettes de papier à chaque cours.'::text),
(303452,33717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre her derste iki kâğıt top ...'::text,'var'::text,'var'::text,'olmak'::text,'Kızım, duyduğuma göre her derste iki kâğıt top var.'::text),
(303453,33717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag minden órán két papírgalacsin ...'::text,'van'::text,'van'::text,'lenni'::text,'Csajszi, állítólag minden órán két papírgalacsin van.'::text),
(320241,35583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie braucht Kraft in beiden ... und Beinen.'::text,'Armen'::text,'Arm'::text,'Armen'::text,'Sie braucht Kraft in beiden Armen und Beinen.'::text),
(320245,35583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй потрібна сила в обох ... і ногах.'::text,'руках'::text,'руці'::text,'руках'::text,'Їй потрібна сила в обох руках і ногах.'::text),
(320244,35583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Necesita fuerza en ambos ... y en las piernas.'::text,'brazos'::text,'brazo'::text,'brazos'::text,'Necesita fuerza en ambos brazos y en las piernas.'::text),
(320243,35583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a besoin de force dans les deux ... et les jambes.'::text,'bras'::text,'bras'::text,'bras'::text,'Elle a besoin de force dans les deux bras et les jambes.'::text),
(320246,35583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hem ... hem de bacaklarında güce ihtiyacı var.'::text,'kollarında'::text,'kolunda'::text,'kollarında'::text,'Hem kollarında hem de bacaklarında güce ihtiyacı var.'::text),
(320247,35583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erő kell neki mindkét ... és a lábában is.'::text,'karjában'::text,'karjában'::text,'karjában'::text,'Erő kell neki mindkét karjában és a lábában is.'::text),
(320250,35584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, Kraft ist ... großer Teil vom Klettern, musst trainieren.'::text,'ein'::text,'ein'::text,'der'::text,'Alter, Kraft ist ein großer Teil vom Klettern, musst trainieren.'::text),
(320254,35584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, сила — це ... велика частина скелелазіння, треба тренуватися.'::text,''::text,NULL::text,NULL::text,'Бро, сила — це велика частина скелелазіння, треба тренуватися.'::text),
(320253,35584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la fuerza es ... parte importante de la escalada, toca entrenar.'::text,'una'::text,'una'::text,'la'::text,'Tío, la fuerza es una parte importante de la escalada, toca entrenar.'::text),
(320252,35584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, la force c''est ... grosse partie de l''escalade, faut s''entraîner.'::text,'une'::text,'une'::text,'la'::text,'Mec, la force c''est une grosse partie de l''escalade, faut s''entraîner.'::text),
(320255,35584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güç tırmanışın büyük ... parçası, antrenman şart.'::text,'bir'::text,'bir'::text,NULL::text,'Kanka, güç tırmanışın büyük bir parçası, antrenman şart.'::text),
(320256,35584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az erő ... nagy része a mászásnak, edzeni kell.'::text,'egy'::text,'egy'::text,'a'::text,'Tesó, az erő egy nagy része a mászásnak, edzeni kell.'::text),
(320259,35585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... Mädchen da oben zeigt gleich ihre Kraft.'::text,'jenes'::text,'diese'::text,'jene'::text,'Alter, jenes Mädchen da oben zeigt gleich ihre Kraft.'::text),
(320263,35585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... дівчина там нагорі зараз покаже свою силу.'::text,'та'::text,'ці'::text,'ті'::text,'Бро, та дівчина там нагорі зараз покаже свою силу.'::text),
(320262,35585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... chica de ahí arriba va a enseñar su fuerza.'::text,'esa'::text,'estas'::text,'esas'::text,'Tío, esa chica de ahí arriba va a enseñar su fuerza.'::text),
(320261,35585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ... fille là-haut va montrer sa force.'::text,'cette'::text,'ces'::text,'ces'::text,'Mec, cette fille là-haut va montrer sa force.'::text),
(320264,35585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yukarıdaki ... kız şimdi gücünü gösterecek.'::text,'şu'::text,'bu'::text,'şu'::text,'Kanka, yukarıdaki şu kız şimdi gücünü gösterecek.'::text),
(320265,35585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a csaj ott fent mindjárt megmutatja az erejét.'::text,'az'::text,'ezek'::text,'azok'::text,'Tesó, az a csaj ott fent mindjárt megmutatja az erejét.'::text),
(320268,35586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Ziel sind 100 Meter. Die Kletterin setzt ... Kraft ein.'::text,'ihre'::text,'seine'::text,'seine'::text,'Das Ziel sind 100 Meter. Die Kletterin setzt ihre Kraft ein.'::text),
(320272,35586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль — 100 метрів. Скелелазка використовує ... силу.'::text,'свою'::text,'свою'::text,'свою'::text,'Ціль — 100 метрів. Скелелазка використовує свою силу.'::text),
(320271,35586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El objetivo son 100 metros. La escaladora usa ... fuerza.'::text,'su'::text,'su'::text,'su'::text,'El objetivo son 100 metros. La escaladora usa su fuerza.'::text),
(320270,35586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''objectif est de 100 mètres. La grimpeuse utilise ... force.'::text,'sa'::text,'sa'::text,'sa'::text,'L''objectif est de 100 mètres. La grimpeuse utilise sa force.'::text),
(320273,35586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedef 100 metre. Tırmanıcı ... gücünü kullanıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Hedef 100 metre. Tırmanıcı onun gücünü kullanıyor.'::text),
(320274,35586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cél 100 méter. A mászó a ... használja.'::text,'erejét'::text,'erejét'::text,'erejét'::text,'A cél 100 méter. A mászó a erejét használja.'::text),
(320277,35587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Kraft ist ... ihren Armen, weil in den Armen die Kraft ist.'::text,'in'::text,'auf'::text,'an'::text,'Ihre Kraft ist in ihren Armen, weil in den Armen die Kraft ist.'::text),
(320281,35587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її сила знаходиться ... руках, бо сила саме в руках.'::text,'у'::text,'на'::text,'біля'::text,'Її сила знаходиться у руках, бо сила саме в руках.'::text),
(320280,35587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su fuerza está ... los brazos, porque la fuerza está en los brazos.'::text,'en'::text,'sobre'::text,'a'::text,'Su fuerza está en los brazos, porque la fuerza está en los brazos.'::text),
(320279,35587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa force est ... ses bras, parce que la force, c''est dans les bras.'::text,'dans'::text,'sur'::text,'à'::text,'Sa force est dans ses bras, parce que la force, c''est dans les bras.'::text),
(320282,35587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun gücü kollarının ..., çünkü güç kollarda olur.'::text,'içinde'::text,'üstünde'::text,NULL::text,'Onun gücü kollarının içinde, çünkü güç kollarda olur.'::text),
(320283,35587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ereje a ... van, mert az erő a karokban van.'::text,'karjában'::text,'karján'::text,'karjánál'::text,'Az ereje a karjában van, mert az erő a karokban van.'::text),
(320286,35588,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! ... Freunde beobachten ihre Kraft von weit unten!'::text,'Zwei'::text,'Zweite'::text,'Zweimal'::text,'Albtraum! Zwei Freunde beobachten ihre Kraft von weit unten!'::text),
(320290,35588,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! ... друзі дивляться на її силу здалеку знизу!'::text,'Два'::text,'Другі'::text,'Двічі'::text,'Жах! Два друзі дивляться на її силу здалеку знизу!'::text),
(320289,35588,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡... amigos miran su fuerza desde muy abajo!'::text,'Dos'::text,'Segundos'::text,'Dos veces'::text,'¡Pesadilla! ¡Dos amigos miran su fuerza desde muy abajo!'::text),
(320288,35588,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! ... amis regardent sa force de tout en bas !'::text,'Deux'::text,'Deuxièmes'::text,'Deux fois'::text,'Cauchemar ! Deux amis regardent sa force de tout en bas !'::text),
(320291,35588,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! ... arkadaş onun gücünü ta aşağıdan izliyor!'::text,'İki'::text,'İkinci'::text,'İki kez'::text,'Kâbus! İki arkadaş onun gücünü ta aşağıdan izliyor!'::text),
(320292,35588,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! ... barát nézi az erejét messze lentről!'::text,'Két'::text,'Második'::text,'Kétszer'::text,'Rémálom! Két barát nézi az erejét messze lentről!'::text),
(302970,33664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Tag ... er spät auf! Das Schlimmste!'::text,'steht'::text,'stehen'::text,'stehend'::text,'Jeden Tag steht er spät auf! Das Schlimmste!'::text),
(302974,33664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щодня він ... пізно! Найгірше!'::text,'встає'::text,'вставати'::text,'встаючи'::text,'Щодня він встає пізно! Найгірше!'::text),
(302973,33664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Todos los días ... tarde! ¡Lo peor!'::text,'se levanta'::text,'levantarse'::text,'levantándose'::text,'¡Todos los días se levanta tarde! ¡Lo peor!'::text),
(302972,33664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tous les jours, il ... tard ! Le pire !'::text,'se lève'::text,'se lever'::text,'se levant'::text,'Tous les jours, il se lève tard ! Le pire !'::text),
(302975,33664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün geç ...! En kötüsü!'::text,'kalkar'::text,'kalkmak'::text,'kalkarak'::text,'Her gün geç kalkar! En kötüsü!'::text),
(302976,33664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nap későn ... fel! A legrosszabb!'::text,'kel'::text,'kelni'::text,'kelő'::text,'Minden nap későn kel fel! A legrosszabb!'::text),
(302979,33665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stopp! ... sie da hinkommen? Sie ist so spät dran!'::text,'Kann'::text,NULL::text,'Ist'::text,'Stopp! Kann sie da hinkommen? Sie ist so spät dran!'::text),
(302983,33665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп! Чи ... вона туди дістатися? Вона так запізнюється!'::text,'може'::text,NULL::text,'є'::text,'Стоп! Чи може вона туди дістатися? Вона так запізнюється!'::text),
(302982,33665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para! ¿... ella llegar allí? ¡Va tardísimo!'::text,'Puede'::text,NULL::text,'Está'::text,'¡Para! ¿Puede ella llegar allí? ¡Va tardísimo!'::text),
(302981,33665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stop ! Est-ce qu''elle ... y arriver ? Elle est tellement en retard !'::text,'peut'::text,NULL::text,'est'::text,'Stop ! Est-ce qu''elle peut y arriver ? Elle est tellement en retard !'::text),
(302984,33665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur! Oraya ... mi? Çok geç kaldı!'::text,'varabilir'::text,NULL::text,NULL::text,'Dur! Oraya varabilir mi? Çok geç kaldı!'::text),
(302985,33665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állj! ... odaérni? Annyira késik!'::text,'Tud'::text,NULL::text,'Van'::text,'Állj! Tud odaérni? Annyira késik!'::text),
(302988,33666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... wacht er spät auf? Weil sein Wecker leise ist.'::text,'Warum'::text,'Wann'::text,'Wo'::text,'Warum wacht er spät auf? Weil sein Wecker leise ist.'::text),
(302992,33666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він прокидається пізно? Бо його будильник тихий.'::text,'Чому'::text,'Коли'::text,'Де'::text,'Чому він прокидається пізно? Бо його будильник тихий.'::text),
(302991,33666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se despierta tarde? Porque su despertador suena bajito.'::text,'Por qué'::text,'Cuándo'::text,'Dónde'::text,'¿Por qué se despierta tarde? Porque su despertador suena bajito.'::text),
(302990,33666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... se réveille-t-il tard ? Parce que son réveil sonne trop doucement.'::text,'Pourquoi'::text,'Quand'::text,'Où'::text,'Pourquoi se réveille-t-il tard ? Parce que son réveil sonne trop doucement.'::text),
(302993,33666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... geç uyanıyor? Çünkü alarmı sessiz.'::text,'Neden'::text,'Ne zaman'::text,'Nerede'::text,'Neden geç uyanıyor? Çünkü alarmı sessiz.'::text),
(302994,33666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ébred későn? Mert halk az ébresztője.'::text,'Miért'::text,'Mikor'::text,'Hol'::text,'Miért ébred későn? Mert halk az ébresztője.'::text),
(302997,33667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute ist er ... als sonst aufgewacht.'::text,'später'::text,'später'::text,'am spätesten'::text,'Heute ist er später als sonst aufgewacht.'::text),
(303001,33667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні він прокинувся ..., ніж зазвичай.'::text,'пізніше'::text,'пізніше'::text,'найпізніше'::text,'Сьогодні він прокинувся пізніше, ніж зазвичай.'::text),
(303000,33667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy se ha despertado ... que de costumbre.'::text,'más tarde'::text,'más tarde'::text,'lo más tarde'::text,'Hoy se ha despertado más tarde que de costumbre.'::text),
(302999,33667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aujourd''hui, il s''est réveillé ... que d''habitude.'::text,'plus tard'::text,'plus tard'::text,'le plus tard'::text,'Aujourd''hui, il s''est réveillé plus tard que d''habitude.'::text),
(303002,33667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün her zamankinden ... uyandı.'::text,'daha geç'::text,'daha geç'::text,'en geç'::text,'Bugün her zamankinden daha geç uyandı.'::text),
(303003,33667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma ... ébredt, mint általában.'::text,'később'::text,'később'::text,'legkésőbb'::text,'Ma később ébredt, mint általában.'::text),
(303015,33669,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline war 9 Uhr, aber sie kam ...'::text,'spät'::text,'neulich'::text,'Verspätung'::text,'Deadline war 9 Uhr, aber sie kam spät.'::text),
(303019,33669,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн був о 9:00, але вона прийшла ...'::text,'пізно'::text,'останнім часом'::text,'запізнення'::text,'Дедлайн був о 9:00, але вона прийшла пізно.'::text),
(303018,33669,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El plazo acababa a las 9:00, pero ella llegó ...'::text,'tarde'::text,'últimamente'::text,'retraso'::text,'El plazo acababa a las 9:00, pero ella llegó tarde.'::text),
(303017,33669,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La deadline était à 9 h, mais elle est arrivée ...'::text,'en retard'::text,'récemment'::text,'retard'::text,'La deadline était à 9 h, mais elle est arrivée en retard.'::text),
(303020,33669,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son teslim saati 9''du ama o ... geldi.'::text,'geç'::text,'son zamanlarda'::text,'gecikme'::text,'Son teslim saati 9''du ama o geç geldi.'::text),
(303021,33669,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A határidő reggel 9 volt, de ő ... érkezett.'::text,'későn'::text,'mostanában'::text,'késés'::text,'A határidő reggel 9 volt, de ő későn érkezett.'::text),
(303024,33670,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist spät aufgewacht, ... er war nicht früh.'::text,'also'::text,'aber'::text,'oder'::text,'Er ist spät aufgewacht, also er war nicht früh.'::text),
(303028,33670,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він прокинувся пізно, ... він був не рано.'::text,'тому'::text,'але'::text,'або'::text,'Він прокинувся пізно, тому він був не рано.'::text),
(303027,33670,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se despertó tarde, ... no fue temprano.'::text,'así que'::text,'pero'::text,'o'::text,'Se despertó tarde, así que no fue temprano.'::text),
(303026,33670,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il s''est réveillé tard, ... il n''était pas en avance.'::text,'donc'::text,'mais'::text,'ou'::text,'Il s''est réveillé tard, donc il n''était pas en avance.'::text),
(303029,33670,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geç uyandı, ... erken değildi.'::text,'bu yüzden'::text,'ama'::text,'veya'::text,'Geç uyandı, bu yüzden erken değildi.'::text),
(303030,33670,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Későn ébredt, ... nem korán ébredt.'::text,'ezért'::text,'de'::text,'vagy'::text,'Későn ébredt, ezért nem korán ébredt.'::text),
(294429,32715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine echt schnelle Maschine, klar. Die Kanne ... sich nach Ewigkeiten endlich.'::text,'füllte'::text,'füllt'::text,'füllen'::text,'Eine echt schnelle Maschine, klar. Die Kanne füllte sich nach Ewigkeiten endlich.'::text),
(294433,32715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже швидка машина, звісно. Глечик нарешті ... через цілу вічність.'::text,'наповнився'::text,'наповнюється'::text,'наповнитися'::text,'Дуже швидка машина, звісно. Глечик нарешті наповнився через цілу вічність.'::text),
(294432,32715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una máquina rapidísima, obviamente. La jarra por fin ... después de siglos.'::text,'se llenó'::text,'se llena'::text,'llenarse'::text,'Una máquina rapidísima, obviamente. La jarra por fin se llenó después de siglos.'::text),
(294431,32715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une machine super rapide, évidemment. La verseuse ... enfin après une éternité.'::text,'s''est remplie'::text,'se remplit'::text,'se remplir'::text,'Une machine super rapide, évidemment. La verseuse s''est remplie enfin après une éternité.'::text),
(294434,32715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçekten hızlı bir makine, belli. Sürahi yıllar sonra nihayet ...'::text,'doldu'::text,'dolar'::text,'dolmak'::text,'Gerçekten hızlı bir makine, belli. Sürahi yıllar sonra nihayet doldu.'::text),
(294435,32715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon gyors gép, nyilván. A kancsó végre ... ezer év után.'::text,'megtelt'::text,'megtelik'::text,'megtelni'::text,'Nagyon gyors gép, nyilván. A kancsó végre megtelt ezer év után.'::text),
(294438,32716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... die langsame Maschine ihr endlich um halb acht den Kaffee.'::text,'machte'::text,'macht'::text,NULL::text,'Gestern machte die langsame Maschine ihr endlich um halb acht den Kaffee.'::text),
(294442,32716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора повільна машина нарешті ... їй каву о пів на восьму.'::text,'зварила'::text,'варить'::text,NULL::text,'Учора повільна машина нарешті зварила їй каву о пів на восьму.'::text),
(294441,32716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer la máquina lenta por fin le ... el café a las siete y media.'::text,'hizo'::text,'hace'::text,NULL::text,'Ayer la máquina lenta por fin le hizo el café a las siete y media.'::text),
(294440,32716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, la machine lente lui ... enfin son café à sept heures et demie.'::text,'a fait'::text,'fait'::text,NULL::text,'Hier, la machine lente lui a fait enfin son café à sept heures et demie.'::text),
(294443,32716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün yavaş makine sonunda kahvesini yedi buçukta ...'::text,'yaptı'::text,'yapar'::text,NULL::text,'Dün yavaş makine sonunda kahvesini yedi buçukta yaptı.'::text),
(294444,32716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a lassú gép végre ... neki a kávét fél nyolckor.'::text,'lefőzte'::text,'lefőzi'::text,NULL::text,'Tegnap a lassú gép végre lefőzte neki a kávét fél nyolckor.'::text),
(294447,32717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Endlich ... der Kaffee jetzt in die Glaskanne.'::text,'tropft'::text,'tropft'::text,'tropft'::text,'Endlich tropft der Kaffee jetzt in die Glaskanne.'::text),
(294451,32717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нарешті кава зараз ... у скляний глечик.'::text,'капає'::text,'капає'::text,'капає'::text,'Нарешті кава зараз капає у скляний глечик.'::text),
(294450,32717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Por fin el café ... ahora en la jarra de cristal.'::text,'está goteando'::text,'gotea'::text,'está goteando'::text,'Por fin el café está goteando ahora en la jarra de cristal.'::text),
(294449,32717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfin, le café ... maintenant dans la verseuse en verre.'::text,'est en train de couler'::text,'coule'::text,'est en train de couler'::text,'Enfin, le café est en train de couler maintenant dans la verseuse en verre.'::text),
(294452,32717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda kahve şimdi cam sürahiye ...'::text,'damlıyor'::text,'damlar'::text,'damlıyor'::text,'Sonunda kahve şimdi cam sürahiye damlıyor.'::text),
(294453,32717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Végre most ... a kávé az üvegkancsóba.'::text,'csöpög'::text,'csöpög'::text,'csöpög'::text,'Végre most csöpög a kávé az üvegkancsóba.'::text),
(294456,32718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise lässt du Kaffee weg, aber heute ... du ihn, endlich. Respekt.'::text,'machst'::text,'machst'::text,NULL::text,'Normalerweise lässt du Kaffee weg, aber heute machst du ihn, endlich. Respekt.'::text),
(294460,32718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти пропускаєш каву, але сьогодні ти її ..., нарешті. Респект.'::text,'готуєш'::text,'готуєш'::text,NULL::text,'Зазвичай ти пропускаєш каву, але сьогодні ти її готуєш, нарешті. Респект.'::text),
(294459,32718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente pasas del café, pero hoy te ... uno, por fin. Chapó.'::text,'estás haciendo'::text,'haces'::text,NULL::text,'Normalmente pasas del café, pero hoy te estás haciendo uno, por fin. Chapó.'::text),
(294458,32718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu zappes le café, mais aujourd''hui, tu ..., enfin. Respect.'::text,'es en train de t''en faire un'::text,'t''en fais un'::text,NULL::text,'D''habitude tu zappes le café, mais aujourd''hui, tu es en train de t''en faire un, enfin. Respect.'::text),
(294461,32718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde kahveyi atlarsın ama bugün ..., sonunda. Saygılar.'::text,'yapıyorsun'::text,'yaparsın'::text,NULL::text,'Genelde kahveyi atlarsın ama bugün yapıyorsun, sonunda. Saygılar.'::text),
(294462,32718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában kihagyod a kávét, de ma végre ... egyet. Respekt.'::text,'főzöl'::text,'főzöl'::text,NULL::text,'Általában kihagyod a kávét, de ma végre főzöl egyet. Respekt.'::text),
(294474,32720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, mit Kaffee endlich im Becher bist du ... als vorher.'::text,'glücklicher'::text,'glücklicher'::text,'am glücklichsten'::text,'Ehrlich, mit Kaffee endlich im Becher bist du glücklicher als vorher.'::text),
(294478,32720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, з кавою нарешті в кухлі ти ..., ніж раніше.'::text,'щасливіший'::text,'більш щасливий'::text,'найщасливіший'::text,'Чесно, з кавою нарешті в кухлі ти щасливіший, ніж раніше.'::text),
(294477,32720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, con el café por fin en tu taza, estás ... que antes.'::text,'más feliz'::text,'más feliz'::text,'el más feliz'::text,'La verdad, con el café por fin en tu taza, estás más feliz que antes.'::text),
(294476,32720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, avec enfin du café dans ton mug, tu es ... qu''avant.'::text,'plus heureux'::text,'plus heureux'::text,'le plus heureux'::text,'Franchement, avec enfin du café dans ton mug, tu es plus heureux qu''avant.'::text),
(294479,32720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, kupanda sonunda kahve varken öncekinden ... duruyorsun.'::text,'daha mutlu'::text,'daha mutlu'::text,'en mutlu'::text,'Açıkçası, kupanda sonunda kahve varken öncekinden daha mutlu duruyorsun.'::text),
(294480,32720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, hogy végre kávé van a bögrédben, ... vagy, mint előtte.'::text,'boldogabb'::text,'boldogabb'::text,'legboldogabb'::text,'Őszintén, hogy végre kávé van a bögrédben, boldogabb vagy, mint előtte.'::text),
(294483,32721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Maschine, klar. Sie tropfte sehr ... und füllte endlich die Kanne.'::text,'langsam'::text,'langsam'::text,'Langsamkeit'::text,'Tolle Maschine, klar. Sie tropfte sehr langsam und füllte endlich die Kanne.'::text),
(294487,32721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова машина, звісно. Вона капала дуже ... і нарешті наповнила глечик.'::text,'повільно'::text,'повільний'::text,'повільність'::text,'Чудова машина, звісно. Вона капала дуже повільно і нарешті наповнила глечик.'::text),
(294486,32721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran máquina, obviamente. Goteó muy ... y por fin llenó la jarra.'::text,'lentamente'::text,'lento'::text,'lentitud'::text,'Gran máquina, obviamente. Goteó muy lentamente y por fin llenó la jarra.'::text),
(294485,32721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super machine, évidemment. Elle a coulé très ... et a enfin rempli la verseuse.'::text,'lentement'::text,'lent'::text,'lenteur'::text,'Super machine, évidemment. Elle a coulé très lentement et a enfin rempli la verseuse.'::text),
(294488,32721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika makine, belli. Çok ... damladı ve sonunda sürahiyi doldurdu.'::text,'yavaşça'::text,'yavaş'::text,'yavaşlık'::text,'Harika makine, belli. Çok yavaşça damladı ve sonunda sürahiyi doldurdu.'::text),
(294489,32721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek gép, nyilván. Nagyon ... csöpögött, és végre megtöltötte a kancsót.'::text,'lassan'::text,'lassú'::text,'lassúság'::text,'Remek gép, nyilván. Nagyon lassan csöpögött, és végre megtöltötte a kancsót.'::text),
(298209,33135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bürstet ihr Haar mit einer Bürste, nicht mit zwei ...'::text,'Bürsten'::text,'Bürste'::text,'Bürsten'::text,'Sie bürstet ihr Haar mit einer Bürste, nicht mit zwei Bürsten.'::text),
(298213,33135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона розчісує волосся однією щіткою, а не двома ...'::text,'щітками'::text,'щіткою'::text,'щітками'::text,'Вона розчісує волосся однією щіткою, а не двома щітками.'::text),
(298212,33135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cepilla el pelo con un cepillo, no con dos ...'::text,'cepillos'::text,'cepillo'::text,'cepillos'::text,'Se cepilla el pelo con un cepillo, no con dos cepillos.'::text),
(298211,33135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se brosse les cheveux avec une brosse, pas avec deux ...'::text,'brosses'::text,'brosse'::text,'brosses'::text,'Elle se brosse les cheveux avec une brosse, pas avec deux brosses.'::text),
(298214,33135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saçını tek bir fırçayla tarıyor, iki ... değil.'::text,'fırçayla'::text,'fırçayla'::text,'fırçayla'::text,'Saçını tek bir fırçayla tarıyor, iki fırçayla değil.'::text),
(298215,33135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kefével fésüli a haját, nem két ...'::text,'kefével'::text,'kefével'::text,'kefével'::text,'Egy kefével fésüli a haját, nem két kefével.'::text),
(298218,33136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bürstet ihr Haar und benutzt dann ... gleiche Bürste für den Hund.'::text,'die'::text,'eine'::text,'eine'::text,'Sie bürstet ihr Haar und benutzt dann die gleiche Bürste für den Hund.'::text),
(298222,33136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона розчісує волосся, а потім використовує ... ту саму щітку для собаки.'::text,''::text,NULL::text,NULL::text,'Вона розчісує волосся, а потім використовує ту саму щітку для собаки.'::text),
(298221,33136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cepilla el pelo y luego usa ... mismo cepillo con el perro.'::text,'el'::text,'un'::text,'un'::text,'Se cepilla el pelo y luego usa el mismo cepillo con el perro.'::text),
(298220,33136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se brosse les cheveux, puis utilise ... même brosse pour le chien.'::text,'la'::text,'une'::text,'une'::text,'Elle se brosse les cheveux, puis utilise la même brosse pour le chien.'::text),
(298223,33136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saçını tarıyor, sonra ... aynı fırçayı köpekte kullanıyor.'::text,''::text,'bir'::text,'bir'::text,'Saçını tarıyor, sonra aynı fırçayı köpekte kullanıyor.'::text),
(298224,33136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megfésüli a haját, aztán ugyanazt ... kefét használja a kutyán.'::text,'a'::text,'egy'::text,'egy'::text,'Megfésüli a haját, aztán ugyanazt a kefét használja a kutyán.'::text),
(298236,33138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau bürstet ... langes dunkles Haar.'::text,'ihr'::text,'sein'::text,'sein'::text,'Die Frau bürstet ihr langes dunkles Haar.'::text),
(298240,33138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка розчісує ... довге темне волосся.'::text,'своє'::text,'своє'::text,'своє'::text,'Жінка розчісує своє довге темне волосся.'::text),
(298239,33138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer se cepilla ... pelo largo y oscuro.'::text,'su'::text,'su'::text,'su'::text,'La mujer se cepilla su pelo largo y oscuro.'::text),
(298238,33138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme brosse ... longs cheveux foncés.'::text,'ses'::text,'ses'::text,'ses'::text,'La femme brosse ses longs cheveux foncés.'::text),
(298241,33138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın ... uzun koyu saçlarını tarıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Kadın onun uzun koyu saçlarını tarıyor.'::text),
(298242,33138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő a hosszú, sötét ... fésüli.'::text,'haját'::text,'haját'::text,'haját'::text,'A nő a hosszú, sötét haját fésüli.'::text),
(298245,33139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Hundehaare sind für immer ... dem Teppich!'::text,'auf'::text,'in'::text,'an'::text,'Katastrophe! Die Hundehaare sind für immer auf dem Teppich!'::text),
(298249,33139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Собача шерсть назавжди ... килимі!'::text,'на'::text,'у'::text,'біля'::text,'Катастрофа! Собача шерсть назавжди на килимі!'::text),
(298248,33139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡El pelo del perro se queda ... la alfombra para siempre!'::text,'en'::text,'en'::text,'a'::text,'¡Desastre! ¡El pelo del perro se queda en la alfombra para siempre!'::text),
(298247,33139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Les poils du chien sont ... le tapis pour toujours !'::text,'sur'::text,'dans'::text,'à'::text,'Catastrophe ! Les poils du chien sont sur le tapis pour toujours !'::text),
(298250,33139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Köpeğin tüyleri sonsuza kadar halının ...!'::text,'üstünde'::text,'içinde'::text,NULL::text,'Felaket! Köpeğin tüyleri sonsuza kadar halının üstünde!'::text),
(298251,33139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A kutya szőre örökre a ... marad!'::text,'szőnyegen'::text,'szőnyegben'::text,'szőnyegnél'::text,'Katasztrófa! A kutya szőre örökre a szőnyegen marad!'::text),
(298254,33140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Frau, ein Hund, ... Bürste für all diese Haare! Katastrophe!'::text,'eine'::text,'erste'::text,'Einsen'::text,'Eine Frau, ein Hund, eine Bürste für all diese Haare! Katastrophe!'::text),
(298258,33140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна жінка, один пес, ... щітка на все це волосся! Катастрофа!'::text,'одна'::text,'перша'::text,'одиниці'::text,'Одна жінка, один пес, одна щітка на все це волосся! Катастрофа!'::text),
(298257,33140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una mujer, un perro, ... cepillo para todo ese pelo! ¡Desastre!'::text,'un'::text,'primer'::text,'un'::text,'¡Una mujer, un perro, un cepillo para todo ese pelo! ¡Desastre!'::text),
(298256,33140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une femme, un chien, ... brosse pour tous ces cheveux ! Catastrophe !'::text,'une'::text,'première'::text,'une'::text,'Une femme, un chien, une brosse pour tous ces cheveux ! Catastrophe !'::text),
(298259,33140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kadın, bir köpek, bütün o tüyler için ... fırça! Felaket!'::text,'bir'::text,'birinci'::text,'birler'::text,'Bir kadın, bir köpek, bütün o tüyler için bir fırça! Felaket!'::text),
(298260,33140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nő, egy kutya, ... kefe ennyi szőrre! Katasztrófa!'::text,'egy'::text,'első'::text,'egyesek'::text,'Egy nő, egy kutya, egy kefe ennyi szőrre! Katasztrófa!'::text),
(298272,33142,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ... langes Haar, also bürstet sie es langsam.'::text,'eine Menge'::text,'viele'::text,'ein paar'::text,'Sie hat eine Menge langes Haar, also bürstet sie es langsam.'::text),
(298276,33142,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї ... довгого волосся, тож вона розчісує його повільно.'::text,'багато'::text,'багато'::text,'кілька'::text,'У неї багато довгого волосся, тож вона розчісує його повільно.'::text),
(298275,33142,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene ... pelo largo, así que se lo cepilla despacio.'::text,'un montón de'::text,'muchos'::text,'unos pocos'::text,'Tiene un montón de pelo largo, así que se lo cepilla despacio.'::text),
(298274,33142,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a ... cheveux longs, alors elle les brosse lentement.'::text,'plein de'::text,'beaucoup de'::text,'quelques'::text,'Elle a plein de cheveux longs, alors elle les brosse lentement.'::text),
(298277,33142,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun ... uzun saçı var, bu yüzden onu yavaşça tarıyor.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Onun çok uzun saçı var, bu yüzden onu yavaşça tarıyor.'::text),
(298278,33142,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hosszú haja van, ezért lassan fésüli.'::text,'Rengeteg'::text,'Sok'::text,'Pár'::text,'Rengeteg hosszú haja van, ezért lassan fésüli.'::text),
(295914,32880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Paprika in einer Pfanne am Meer.'::text,'brät'::text,'braten'::text,'bratend'::text,'Er brät Paprika in einer Pfanne am Meer.'::text),
(295918,32880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... перець на сковорідці біля моря.'::text,'смажить'::text,'смажити'::text,'смажачи'::text,'Він смажить перець на сковорідці біля моря.'::text),
(295917,32880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... pimientos en una sartén junto al mar.'::text,'fríe'::text,'freír'::text,'friendo'::text,'Él fríe pimientos en una sartén junto al mar.'::text),
(295916,32880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des poivrons à la poêle au bord de la mer.'::text,'fait frire'::text,'faire frire'::text,'faisant frire'::text,'Il fait frire des poivrons à la poêle au bord de la mer.'::text),
(295919,32880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz kenarında tavada biber ...'::text,'kızartır'::text,'kızartmak'::text,'kızartarak'::text,'Deniz kenarında tavada biber kızartır.'::text),
(295920,32880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paprikát ... egy serpenyőben a tenger mellett.'::text,'süt'::text,'sütni'::text,'sütő'::text,'Paprikát süt egy serpenyőben a tenger mellett.'::text),
(295932,32882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... brät er Fisch? In einem winzigen Van! Wahnsinn!'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo brät er Fisch? In einem winzigen Van! Wahnsinn!'::text),
(295936,32882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він смажить рибу? У крихітному фургоні! Божевілля!'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де він смажить рибу? У крихітному фургоні! Божевілля!'::text),
(295935,32882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... fríe pescado? ¡En una furgoneta diminuta! ¡Qué locura!'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde fríe pescado? ¡En una furgoneta diminuta! ¡Qué locura!'::text),
(295934,32882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fait-il frire du poisson ? Dans un minuscule van ! C''est dingue !'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où fait-il frire du poisson ? Dans un minuscule van ! C''est dingue !'::text),
(295937,32882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balığı ... kızartıyor? Minicik bir minibüste! Delilik!'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'Balığı nerede kızartıyor? Minicik bir minibüste! Delilik!'::text),
(295938,32882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... süt halat? Egy pici furgonban! Őrület!'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol süt halat? Egy pici furgonban! Őrület!'::text),
(295941,32883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzte Woche ... er hier Fisch und hätte fast den Van abgefackelt!'::text,'briet'::text,'brät'::text,'braten'::text,'Letzte Woche briet er hier Fisch und hätte fast den Van abgefackelt!'::text),
(295945,32883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого тижня він тут ... рибу і ледь не спалив фургон!'::text,'смажив'::text,'смажить'::text,'смажити'::text,'Минулого тижня він тут смажив рибу і ледь не спалив фургон!'::text),
(295944,32883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La semana pasada ... pescado aquí y casi quema la furgoneta!'::text,'frió'::text,'fríe'::text,'freír'::text,'¡La semana pasada frió pescado aquí y casi quema la furgoneta!'::text),
(295943,32883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine dernière, il ... du poisson ici et a failli cramer le van !'::text,'a fait frire'::text,'fait frire'::text,'faire frire'::text,'La semaine dernière, il a fait frire du poisson ici et a failli cramer le van !'::text),
(295946,32883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen hafta burada balık ... ve neredeyse minibüsü yakıyordu!'::text,'kızarttı'::text,'kızartır'::text,'kızartmak'::text,'Geçen hafta burada balık kızarttı ve neredeyse minibüsü yakıyordu!'::text),
(295947,32883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Múlt héten itt halat ..., és majdnem felgyújtotta a furgont!'::text,'sütött'::text,'süt'::text,'sütni'::text,'Múlt héten itt halat sütött, és majdnem felgyújtotta a furgont!'::text),
(295950,32884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich brät er jeden Tag Eier, aber gestern ... er Fisch.'::text,'briet'::text,'brät'::text,NULL::text,'Girl, angeblich brät er jeden Tag Eier, aber gestern briet er Fisch.'::text),
(295954,32884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він щодня смажить яйця, але вчора він ... рибу.'::text,'смажив'::text,'смажить'::text,NULL::text,'Подруго, кажуть, він щодня смажить яйця, але вчора він смажив рибу.'::text),
(295953,32884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer fríe huevos a diario, pero ayer ... pescado.'::text,'frió'::text,'fríe'::text,NULL::text,'Tía, al parecer fríe huevos a diario, pero ayer frió pescado.'::text),
(295952,32884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il fait frire des œufs tous les jours, mais hier il ... du poisson.'::text,'a fait frire'::text,'fait frire'::text,NULL::text,'Meuf, apparemment il fait frire des œufs tous les jours, mais hier il a fait frire du poisson.'::text),
(295955,32884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre her gün yumurta kızartıyormuş ama dün balık ...'::text,'kızarttı'::text,'kızartır'::text,NULL::text,'Kızım, duyduğuma göre her gün yumurta kızartıyormuş ama dün balık kızarttı.'::text),
(295956,32884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag minden nap tojást süt, de tegnap halat ...'::text,'sütött'::text,'süt'::text,NULL::text,'Csajszi, állítólag minden nap tojást süt, de tegnap halat sütött.'::text),
(295959,32885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ist das die Campingplatz-Regel: Er ... in der Tür braten.'::text,'muss'::text,'muss'::text,'sollte'::text,'Hör zu, angeblich ist das die Campingplatz-Regel: Er muss in der Tür braten.'::text),
(295963,32885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, це правило кемпінгу: він ... смажити у дверях.'::text,'має'::text,'мусить'::text,'мав би'::text,'Слухай, кажуть, це правило кемпінгу: він має смажити у дверях.'::text),
(295962,32885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer es la norma del camping: él ... freír en la puerta.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Oye, al parecer es la norma del camping: él tiene que freír en la puerta.'::text),
(295961,32885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment c''est la règle du camping : il ... faire frire à la porte.'::text,'doit'::text,'doit'::text,'devrait'::text,'Écoute, apparemment c''est la règle du camping : il doit faire frire à la porte.'::text),
(295964,32885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre kamp alanının kuralıymış: kapının önünde ...'::text,'kızartmak zorunda'::text,'kızartmalı'::text,'kızartmalı'::text,'Dinle, duyduğuma göre kamp alanının kuralıymış: kapının önünde kızartmak zorunda.'::text),
(295965,32885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ez a kemping szabálya: az ajtóban ... sütnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Figyelj, állítólag ez a kemping szabálya: az ajtóban kell sütnie.'::text),
(295968,32886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, du ... den Fisch neben der Paprika braten. Wird legendär.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Alter, du solltest den Fisch neben der Paprika braten. Wird legendär.'::text),
(295972,32886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти ... смажити рибу поруч із перцем. Буде топ.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Бро, ти мав би смажити рибу поруч із перцем. Буде топ.'::text),
(295971,32886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... freír el pescado junto a los pimientos. Va a quedar top.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tío, deberías freír el pescado junto a los pimientos. Va a quedar top.'::text),
(295970,32886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, tu ... faire frire le poisson à côté des poivrons. Ça va être le feu.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Mec, tu devrais faire frire le poisson à côté des poivrons. Ça va être le feu.'::text),
(295973,32886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, balığı biberlerin yanında ... Efsane olacak.'::text,'kızartmalısın'::text,'kızartacaksın'::text,'kızartmalısın'::text,'Kanka, balığı biberlerin yanında kızartmalısın Efsane olacak.'::text),
(295974,32886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a halat a paprika mellett ... sütnöd. Brutál lesz.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Tesó, a halat a paprika mellett kellene sütnöd. Brutál lesz.'::text),
(311214,34580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Dorfbewohner ... das Boot ins Meer.'::text,'schieben'::text,'schiebt'::text,'schiebend'::text,'Die Dorfbewohner schieben das Boot ins Meer.'::text),
(311218,34580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Селяни ... човен у море.'::text,'штовхають'::text,'штовхає'::text,'штовхаючи'::text,'Селяни штовхають човен у море.'::text),
(311217,34580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los vecinos del pueblo ... la barca al mar.'::text,'empujan'::text,'empuja'::text,'empujando'::text,'Los vecinos del pueblo empujan la barca al mar.'::text),
(311216,34580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les villageois ... le bateau vers la mer.'::text,'poussent'::text,'pousse'::text,'poussant'::text,'Les villageois poussent le bateau vers la mer.'::text),
(311219,34580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köylüler tekneyi denize ...'::text,'iterler'::text,'iter'::text,'iterek'::text,'Köylüler tekneyi denize iterler.'::text),
(311220,34580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A falusiak a tengerbe ... a csónakot.'::text,'tolják'::text,'tolja'::text,'toló'::text,'A falusiak a tengerbe tolják a csónakot.'::text),
(311223,34581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Mann ... das große Boot nicht allein schieben.'::text,'kann'::text,'kann'::text,'ist'::text,'Ein Mann kann das große Boot nicht allein schieben.'::text),
(311227,34581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один чоловік не ... сам штовхати великий човен.'::text,'може'::text,'може'::text,'є'::text,'Один чоловік не може сам штовхати великий човен.'::text),
(311226,34581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hombre no ... empujar solo la barca grande.'::text,'puede'::text,'puede'::text,'está'::text,'Un hombre no puede empujar solo la barca grande.'::text),
(311225,34581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme ne ... pas pousser le gros bateau tout seul.'::text,'peut'::text,'peut'::text,'est'::text,'Un homme ne peut pas pousser le gros bateau tout seul.'::text),
(311228,34581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir adam büyük tekneyi tek başına ...'::text,'itemez'::text,'itemez'::text,NULL::text,'Tek bir adam büyük tekneyi tek başına itemez.'::text),
(311229,34581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy ember nem ... egyedül eltolni a nagy csónakot.'::text,'tudja'::text,'tudja'::text,'van'::text,'Egy ember nem tudja egyedül eltolni a nagy csónakot.'::text),
(311241,34583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, bei drei ... sie das Boot schieben, ohne Witz.'::text,'werden'::text,'wird'::text,'werden'::text,'Alter, bei drei werden sie das Boot schieben, ohne Witz.'::text),
(311245,34583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, на рахунок три вони ... штовхати човен, чесно.'::text,'збираються'::text,'збирається'::text,'збираються'::text,'Бро, на рахунок три вони збираються штовхати човен, чесно.'::text),
(311244,34583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, a la de tres ... empujar la barca, en serio.'::text,'van a'::text,'va a'::text,'van a'::text,'Tío, a la de tres van a empujar la barca, en serio.'::text),
(311243,34583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, à trois, ils ... pousser le bateau, sans mentir.'::text,'vont'::text,'va'::text,'vont'::text,'Mec, à trois, ils vont pousser le bateau, sans mentir.'::text),
(311246,34583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, üç deyince tekneyi ..., yemin ederim.'::text,'itecekler'::text,'itecek'::text,'itecekler'::text,'Kanka, üç deyince tekneyi itecekler, yemin ederim.'::text),
(311247,34583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, háromra ... tolni a csónakot, komolyan.'::text,'fogják'::text,'fogja'::text,'fogják'::text,'Tesó, háromra fogják tolni a csónakot, komolyan.'::text),
(311250,34584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap: Um 6 Uhr ... die Dorfbewohner das Boot schieben.'::text,'werden'::text,'werden'::text,NULL::text,'Roadmap: Um 6 Uhr werden die Dorfbewohner das Boot schieben.'::text),
(311254,34584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Роадмап: о 6:00 селяни ... штовхати човен.'::text,'збираються'::text,'будуть'::text,NULL::text,'Роадмап: о 6:00 селяни збираються штовхати човен.'::text),
(311253,34584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta: a las 6:00, los vecinos ... empujar la barca.'::text,'van a'::text,NULL::text,NULL::text,'Hoja de ruta: a las 6:00, los vecinos van a empujar la barca.'::text),
(311252,34584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feuille de route : à 6 h, les villageois ... pousser le bateau.'::text,'vont'::text,NULL::text,NULL::text,'Feuille de route : à 6 h, les villageois vont pousser le bateau.'::text),
(311255,34584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol haritası: saat 6''da köylüler tekneyi ...'::text,'itecekler'::text,'itecekler'::text,NULL::text,'Yol haritası: saat 6''da köylüler tekneyi itecekler.'::text),
(311256,34584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütemterv: reggel 6-kor a falusiak ... tolni a csónakot.'::text,'fogják'::text,'fogják'::text,NULL::text,'Ütemterv: reggel 6-kor a falusiak fogják tolni a csónakot.'::text),
(311259,34585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Boot ist sehr schwer, also ... alle zusammen schieben.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Das Boot ist sehr schwer, also müssen alle zusammen schieben.'::text),
(311263,34585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Човен дуже важкий, тож усі ... штовхати разом.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Човен дуже важкий, тож усі мають штовхати разом.'::text),
(311262,34585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La barca pesa mucho, así que todos ... empujar juntos.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'La barca pesa mucho, así que todos tienen que empujar juntos.'::text),
(311261,34585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau est très lourd, donc tout le monde ... pousser ensemble.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le bateau est très lourd, donc tout le monde doit pousser ensemble.'::text),
(311264,34585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tekne çok ağır, bu yüzden herkes birlikte ...'::text,'itmek zorunda'::text,'itmeli'::text,'itmeli'::text,'Tekne çok ağır, bu yüzden herkes birlikte itmek zorunda.'::text),
(311265,34585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csónak nagyon nehéz, ezért mindenkinek együtt ... tolnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'A csónak nagyon nehéz, ezért mindenkinek együtt kell tolnia.'::text),
(311277,34587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, ihr schiebt alle voll, ... erreicht das Boot das Meer.'::text,'also'::text,'aber'::text,'weil'::text,'Respekt, ihr schiebt alle voll, also erreicht das Boot das Meer.'::text),
(311281,34587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ви всі штовхаєте щосили, ... човен дістається моря.'::text,'тому'::text,'але'::text,'бо'::text,'Респект, ви всі штовхаєте щосили, тому човен дістається моря.'::text),
(311280,34587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chapó, empujáis todos con fuerza, ... la barca llega al mar.'::text,'así que'::text,'pero'::text,'porque'::text,'Chapó, empujáis todos con fuerza, así que la barca llega al mar.'::text),
(311279,34587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, vous poussez tous fort, ... le bateau atteint la mer.'::text,'donc'::text,'mais'::text,'parce que'::text,'Respect, vous poussez tous fort, donc le bateau atteint la mer.'::text),
(311282,34587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, hepiniz güçlü itiyorsunuz, ... tekne denize ulaşıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Saygılar, hepiniz güçlü itiyorsunuz, bu yüzden tekne denize ulaşıyor.'::text),
(311283,34587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, mind erősen toljátok, ... a csónak eléri a tengert.'::text,'ezért'::text,'de'::text,'mert'::text,'Respekt, mind erősen toljátok, ezért a csónak eléri a tengert.'::text),
(315597,35067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schiff ... orange Rettungsboote.'::text,'hat'::text,'haben'::text,'ist'::text,'Das Schiff hat orange Rettungsboote.'::text),
(315601,35067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корабель ... помаранчеві рятувальні шлюпки.'::text,'має'::text,'мати'::text,'є'::text,'Корабель має помаранчеві рятувальні шлюпки.'::text),
(315600,35067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco ... botes salvavidas naranjas.'::text,'tiene'::text,'tienen'::text,'está'::text,'El barco tiene botes salvavidas naranjas.'::text),
(315599,35067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le navire ... des canots de sauvetage orange.'::text,'a'::text,'ont'::text,'est'::text,'Le navire a des canots de sauvetage orange.'::text),
(315602,35067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geminin turuncu filikaları ...'::text,'var'::text,'var'::text,NULL::text,'Geminin turuncu filikaları var.'::text),
(315603,35067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajónak narancssárga mentőcsónakjai ...'::text,'vannak'::text,'vannak'::text,'vannak'::text,'A hajónak narancssárga mentőcsónakjai vannak.'::text),
(315606,35068,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schiff hat zwei ... auf dem Oberdeck.'::text,'Schornsteine'::text,'Schornstein'::text,'Schornsteine'::text,'Das Schiff hat zwei Schornsteine auf dem Oberdeck.'::text),
(315610,35068,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корабель має дві ... на верхній палубі.'::text,'труби'::text,'трубу'::text,'труби'::text,'Корабель має дві труби на верхній палубі.'::text),
(315609,35068,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco tiene dos ... en la cubierta superior.'::text,'chimeneas'::text,'chimenea'::text,'chimeneas'::text,'El barco tiene dos chimeneas en la cubierta superior.'::text),
(315608,35068,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le navire a deux ... sur le pont supérieur.'::text,'cheminées'::text,'cheminée'::text,'cheminées'::text,'Le navire a deux cheminées sur le pont supérieur.'::text),
(315611,35068,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geminin üst güvertesinde iki ... var.'::text,'baca'::text,'baca'::text,'baca'::text,'Geminin üst güvertesinde iki baca var.'::text),
(315612,35068,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajónak két ... van a felső fedélzeten.'::text,'kéménye'::text,'kéménye'::text,'kéménye'::text,'A hajónak két kéménye van a felső fedélzeten.'::text),
(315615,35069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie geht zu einem großen Schiff. ... Schiff hat einen Pool.'::text,'Das'::text,'Ein'::text,'Ein'::text,'Sie geht zu einem großen Schiff. Das Schiff hat einen Pool.'::text),
(315619,35069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона йде до великого корабля. ... Корабель має басейн.'::text,''::text,NULL::text,NULL::text,'Вона йде до великого корабля. Корабель має басейн.'::text),
(315618,35069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Camina hacia un barco grande. ... barco tiene piscina.'::text,'El'::text,'Un'::text,'Un'::text,'Camina hacia un barco grande. El barco tiene piscina.'::text),
(315617,35069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle marche vers un grand navire. ... navire a une piscine.'::text,'Le'::text,'Un'::text,'Un'::text,'Elle marche vers un grand navire. Le navire a une piscine.'::text),
(315620,35069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük bir gemiye doğru yürüyor. ... Geminin havuzu var.'::text,''::text,'Bir'::text,'Bir'::text,'Büyük bir gemiye doğru yürüyor. Geminin havuzu var.'::text),
(315621,35069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nagy hajóhoz sétál. ... hajónak van medencéje.'::text,'A'::text,'Egy'::text,'Egy'::text,'Egy nagy hajóhoz sétál. A hajónak van medencéje.'::text),
(315624,35070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Schiff ist groß, weil es ein großes Schiff ist.'::text,'Dieses'::text,'Diese'::text,'Jene'::text,'Dieses Schiff ist groß, weil es ein großes Schiff ist.'::text),
(315628,35070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... корабель великий, бо це великий корабель.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей корабель великий, бо це великий корабель.'::text),
(315627,35070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... barco es grande porque es un barco grande.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este barco es grande porque es un barco grande.'::text),
(315626,35070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... navire est grand parce que c''est un grand navire.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce navire est grand parce que c''est un grand navire.'::text),
(315629,35070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gemi büyük, çünkü büyük bir gemi.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu gemi büyük, çünkü büyük bir gemi.'::text),
(315630,35070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a hajó nagy, mert ez egy nagy hajó.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a hajó nagy, mert ez egy nagy hajó.'::text),
(315651,35073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schlimmste! Sie hat zu ... Fotos vom Schiff gemacht!'::text,'viele'::text,'viel'::text,'eine Menge'::text,'Das Schlimmste! Sie hat zu viele Fotos vom Schiff gemacht!'::text),
(315655,35073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірше! Вона зробила занадто ... фото корабля!'::text,'багато'::text,'багато'::text,'багато'::text,'Найгірше! Вона зробила занадто багато фото корабля!'::text),
