(315653,35073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pire ! Elle a pris ... photos du navire, c''est trop !'::text,'beaucoup de'::text,'beaucoup de'::text,'plein de'::text,'Le pire ! Elle a pris beaucoup de photos du navire, c''est trop !'::text),
(315656,35073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En kötüsü! Geminin ... fazla fotoğrafını çekti!'::text,'çok'::text,'çok'::text,'çok'::text,'En kötüsü! Geminin çok fazla fotoğrafını çekti!'::text),
