(315660,35074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, auf dem Schiff ... zwei Pools.'::text,'sind'::text,'ist'::text,'sein'::text,'Girl, ich hab gehört, auf dem Schiff sind zwei Pools.'::text),
(315664,35074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що на тому кораблі ... два басейни.'::text,'є'::text,'є'::text,'бути'::text,'Подруго, я чула, що на тому кораблі є два басейни.'::text),
(315663,35074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que en ese barco ... dos piscinas.'::text,'hay'::text,'hay'::text,'hay'::text,'Tía, me han dicho que en ese barco hay dos piscinas.'::text),
(315662,35074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, on m''a dit que sur ce navire, ... deux piscines.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Meuf, on m''a dit que sur ce navire, il y a deux piscines.'::text),
(315665,35074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki o gemide iki havuz ...'::text,'var'::text,'var'::text,'olmak'::text,'Kızım, duydum ki o gemide iki havuz var.'::text),
(315666,35074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy azon a hajón két medence ...'::text,'van'::text,'van'::text,'lenni'::text,'Csajszi, azt hallottam, hogy azon a hajón két medence van.'::text),
(300387,33377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Krankenhausflur ... auf beiden Seiten lange Handläufe.'::text,'hat'::text,'haben'::text,'hat'::text,'Der Krankenhausflur hat auf beiden Seiten lange Handläufe.'::text),
(300391,33377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікарняний коридор ... довгі поручні з обох боків.'::text,'має'::text,'мати'::text,'має'::text,'Лікарняний коридор має довгі поручні з обох боків.'::text),
(300390,33377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pasillo del hospital ... pasamanos largos a ambos lados.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El pasillo del hospital tiene pasamanos largos a ambos lados.'::text),
(300389,33377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le couloir de l''hôpital ... de longues rampes des deux côtés.'::text,'a'::text,'ont'::text,'a'::text,'Le couloir de l''hôpital a de longues rampes des deux côtés.'::text),
(300392,33377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastane koridorunun iki yanında uzun tırabzanlar ...'::text,'var'::text,'var'::text,'var'::text,'Hastane koridorunun iki yanında uzun tırabzanlar var.'::text),
(300393,33377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kórházi folyosónak mindkét oldalán hosszú korlátjai ...'::text,'vannak'::text,'vannak'::text,'vannak'::text,'A kórházi folyosónak mindkét oldalán hosszú korlátjai vannak.'::text),
(300396,33378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei ... im Krankenhausflur und ein kaputter Fuß! Katastrophe!'::text,'Krücken'::text,'Krücke'::text,'Krücken'::text,'Zwei Krücken im Krankenhausflur und ein kaputter Fuß! Katastrophe!'::text),
(300400,33378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві ... в лікарняному коридорі й одна хвора нога! Катастрофа!'::text,'милиці'::text,'милиця'::text,'милиці'::text,'Дві милиці в лікарняному коридорі й одна хвора нога! Катастрофа!'::text),
(300399,33378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dos ... en el pasillo del hospital y un pie fatal! ¡Desastre!'::text,'muletas'::text,'muleta'::text,'muletas'::text,'¡Dos muletas en el pasillo del hospital y un pie fatal! ¡Desastre!'::text),
(300398,33378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux ... dans le couloir de l''hôpital et un pied en vrac ! Catastrophe !'::text,'béquilles'::text,'béquille'::text,'béquilles'::text,'Deux béquilles dans le couloir de l''hôpital et un pied en vrac ! Catastrophe !'::text),
(300401,33378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastane koridorunda iki ... ve bir sakat ayak! Felaket!'::text,'koltuk değneği'::text,'koltuk değneği'::text,'koltuk değneği'::text,'Hastane koridorunda iki koltuk değneği ve bir sakat ayak! Felaket!'::text),
(300402,33378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ... a kórházi folyosón és egy rossz láb! Katasztrófa!'::text,'mankó'::text,'mankó'::text,'mankó'::text,'Két mankó a kórházi folyosón és egy rossz láb! Katasztrófa!'::text),
(300405,33379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist kein Hotel! Das ist ... Krankenhaus, und er hasst es!'::text,'ein'::text,'ein'::text,'das'::text,'Das ist kein Hotel! Das ist ein Krankenhaus, und er hasst es!'::text),
(300409,33379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це не готель! Це ... лікарня, і він її ненавидить!'::text,''::text,NULL::text,NULL::text,'Це не готель! Це лікарня, і він її ненавидить!'::text),
(300408,33379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esto no es un hotel! ¡Es ... hospital, y lo odia!'::text,'un'::text,'un'::text,'el'::text,'¡Esto no es un hotel! ¡Es un hospital, y lo odia!'::text),
(300407,33379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est pas un hôtel ! C''est ... hôpital, et il déteste ça !'::text,'un'::text,'un'::text,'l'''::text,'Ce n''est pas un hôtel ! C''est un hôpital, et il déteste ça !'::text),
(300410,33379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burası otel değil! Burası ... hastane ve o bundan nefret ediyor!'::text,'bir'::text,'bir'::text,NULL::text,'Burası otel değil! Burası bir hastane ve o bundan nefret ediyor!'::text),
(300411,33379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez nem hotel! Ez ... kórház, és utálja!'::text,'egy'::text,'egy'::text,'a'::text,'Ez nem hotel! Ez egy kórház, és utálja!'::text),
(300414,33380,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pflegerin folgt ihm ... langen Krankenhausflur entlang.'::text,'diesen'::text,'diese'::text,'jene'::text,'Die Pflegerin folgt ihm diesen langen Krankenhausflur entlang.'::text),
(300418,33380,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра йде за ним ... довгим лікарняним коридором.'::text,'цим'::text,'цими'::text,'тими'::text,'Медсестра йде за ним цим довгим лікарняним коридором.'::text),
(300417,33380,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enfermera lo sigue por ... largo pasillo del hospital.'::text,'este'::text,'estos'::text,'esos'::text,'La enfermera lo sigue por este largo pasillo del hospital.'::text),
(300416,33380,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière le suit dans ... long couloir d''hôpital.'::text,'ce'::text,'ces'::text,'ces'::text,'L''infirmière le suit dans ce long couloir d''hôpital.'::text),
(300419,33380,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire onu ... uzun hastane koridorunda takip ediyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Hemşire onu bu uzun hastane koridorunda takip ediyor.'::text),
(300420,33380,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ápolónő követi őt ... hosszú kórházi folyosón.'::text,'ezen a'::text,'ezeken a'::text,'azokon a'::text,'Az ápolónő követi őt ezen a hosszú kórházi folyosón.'::text),
(300423,33381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er geht auf ... Krücken den Krankenhausflur entlang.'::text,'seinen'::text,'ihren'::text,'seinen'::text,'Er geht auf seinen Krücken den Krankenhausflur entlang.'::text),
(300427,33381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він іде лікарняним коридором на ... милицях.'::text,'своїх'::text,'своїх'::text,'своїх'::text,'Він іде лікарняним коридором на своїх милицях.'::text),
(300426,33381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Recorre el pasillo del hospital con ... muletas.'::text,'sus'::text,'sus'::text,'sus'::text,'Recorre el pasillo del hospital con sus muletas.'::text),
(300425,33381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il avance dans le couloir de l''hôpital avec ... béquilles.'::text,'ses'::text,'ses'::text,'ses'::text,'Il avance dans le couloir de l''hôpital avec ses béquilles.'::text),
(300428,33381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastane koridorunda ... koltuk değnekleriyle yürüyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Hastane koridorunda onun koltuk değnekleriyle yürüyor.'::text),
(300429,33381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ... sétál végig a kórházi folyosón.'::text,'mankóival'::text,'mankóival'::text,'mankóival'::text,'A mankóival sétál végig a kórházi folyosón.'::text),
(300441,33383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du gehst auf ... Krücken durch den Krankenhausflur. Ehrlich, beeindruckend.'::text,'zwei'::text,'zweiten'::text,'Zweien'::text,'Du gehst auf zwei Krücken durch den Krankenhausflur. Ehrlich, beeindruckend.'::text),
(300445,33383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти йдеш лікарняним коридором на ... милицях. Чесно, вражає.'::text,'двох'::text,'других'::text,'двійках'::text,'Ти йдеш лікарняним коридором на двох милицях. Чесно, вражає.'::text),
(300444,33383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Recorres el pasillo del hospital con ... muletas. La verdad, impresionante.'::text,'dos'::text,'segundas'::text,'dos'::text,'Recorres el pasillo del hospital con dos muletas. La verdad, impresionante.'::text),
(300443,33383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu traverses le couloir de l''hôpital sur ... béquilles. Franchement, impressionnant.'::text,'deux'::text,'deuxièmes'::text,'deux'::text,'Tu traverses le couloir de l''hôpital sur deux béquilles. Franchement, impressionnant.'::text),
(300446,33383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastane koridorunda ... koltuk değneğiyle yürüyorsun. Açıkçası etkileyici.'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Hastane koridorunda iki koltuk değneğiyle yürüyorsun. Açıkçası etkileyici.'::text),
(300447,33383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mankóval mész végig a kórházi folyosón. Őszintén, lenyűgöző.'::text,'Két'::text,'Második'::text,'Kettesek'::text,'Két mankóval mész végig a kórházi folyosón. Őszintén, lenyűgöző.'::text),
(323247,35917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... sie auf der Party die ganze Nacht zusammen.'::text,'weinten'::text,'weinten'::text,'weint'::text,'Girl, angeblich weinten sie auf der Party die ganze Nacht zusammen.'::text),
(323251,35917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вони ... разом усю ніч на вечірці.'::text,'плакали'::text,'плакали'::text,'плаче'::text,'Подруго, кажуть, вони плакали разом усю ніч на вечірці.'::text),
(323250,35917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... juntos toda la noche en la fiesta.'::text,'lloraron'::text,'lloraron'::text,'llora'::text,'Tía, al parecer lloraron juntos toda la noche en la fiesta.'::text),
(323249,35917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ils ... ensemble toute la nuit à la soirée.'::text,'ont pleuré'::text,'ont pleuré'::text,'pleure'::text,'Meuf, apparemment ils ont pleuré ensemble toute la nuit à la soirée.'::text),
(323252,35917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre partide bütün gece birlikte ...'::text,'ağladılar'::text,'ağladılar'::text,'ağlar'::text,'Kızım, duyduğuma göre partide bütün gece birlikte ağladılar.'::text),
(323253,35917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egész éjjel együtt ... a buliban.'::text,'sírtak'::text,'sírtak'::text,'sír'::text,'Csajszi, állítólag egész éjjel együtt sírtak a buliban.'::text),
(323256,35918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie jetzt jeden Freitag zusammen aus.'::text,'gehen'::text,'gingen'::text,NULL::text,'Bestie, angeblich gehen sie jetzt jeden Freitag zusammen aus.'::text),
(323260,35918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вони тепер щоп''ятниці ... кудись разом.'::text,'ходять'::text,'ходили'::text,NULL::text,'Подружко, кажуть, вони тепер щоп''ятниці ходять кудись разом.'::text),
(323259,35918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ahora ... de fiesta juntos todos los viernes.'::text,'salen'::text,'salieron'::text,NULL::text,'Amiga, al parecer ahora salen de fiesta juntos todos los viernes.'::text),
(323258,35918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma pote, apparemment ils ... ensemble tous les vendredis maintenant.'::text,'sortent'::text,'sont sortis'::text,NULL::text,'Ma pote, apparemment ils sortent ensemble tous les vendredis maintenant.'::text),
(323261,35918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre artık her cuma birlikte dışarı ...'::text,'çıkarlar'::text,'çıktılar'::text,NULL::text,'Kanka, duyduğuma göre artık her cuma birlikte dışarı çıkarlar.'::text),
(323262,35918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, állítólag most minden pénteken együtt ... el.'::text,'mennek'::text,'mentek'::text,NULL::text,'Bestie, állítólag most minden pénteken együtt mennek el.'::text),
(323265,35919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, sie ... gerade zusammen im Flur.'::text,'weinen'::text,'weinen'::text,'weinen'::text,'Okay, also ich hab gehört, sie weinen gerade zusammen im Flur.'::text),
(323269,35919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що вони саме зараз ... разом у коридорі.'::text,'плачуть'::text,'плачуть'::text,'плачуть'::text,'Коротше, я чула, що вони саме зараз плачуть разом у коридорі.'::text),
(323268,35919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me han dicho que ahora mismo ... juntos en el pasillo.'::text,'están llorando'::text,'lloran'::text,'están llorando'::text,'Vale, me han dicho que ahora mismo están llorando juntos en el pasillo.'::text),
(323267,35919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu qu''ils ... ensemble dans le couloir en ce moment.'::text,'sont en train de pleurer'::text,'pleurent'::text,'sont en train de pleurer'::text,'Bon, j''ai entendu qu''ils sont en train de pleurer ensemble dans le couloir en ce moment.'::text),
(323270,35919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam bak, duydum ki şu an koridorda birlikte ...'::text,'ağlıyorlar'::text,'ağlarlar'::text,'ağlıyorlar'::text,'Tamam bak, duydum ki şu an koridorda birlikte ağlıyorlar.'::text),
(323271,35919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, figyu, azt hallottam, hogy most épp együtt ... a folyosón.'::text,'sírnak'::text,'sírnak'::text,'sírnak'::text,'Oké, figyu, azt hallottam, hogy most épp együtt sírnak a folyosón.'::text),
(323274,35920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr lacht alle viel, aber gerade ... ihr zusammen, ehrlich.'::text,'weint'::text,'weint'::text,NULL::text,'Ihr lacht alle viel, aber gerade weint ihr zusammen, ehrlich.'::text),
(323278,35920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ви всі багато смієтеся, але саме зараз ви ... разом, чесно.'::text,'плачете'::text,'плачете'::text,NULL::text,'Ви всі багато смієтеся, але саме зараз ви плачете разом, чесно.'::text),
(323277,35920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Os reís mucho todos, pero ahora mismo ... juntos, la verdad.'::text,'estáis llorando'::text,'lloráis'::text,NULL::text,'Os reís mucho todos, pero ahora mismo estáis llorando juntos, la verdad.'::text),
(323276,35920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vous riez tous beaucoup, mais là, vous ... ensemble, franchement.'::text,'êtes en train de pleurer'::text,'pleurez'::text,NULL::text,'Vous riez tous beaucoup, mais là, vous êtes en train de pleurer ensemble, franchement.'::text),
(323279,35920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hepiniz çok gülersiniz ama şu an birlikte ..., açıkçası.'::text,'ağlıyorsunuz'::text,'ağlarsınız'::text,NULL::text,'Hepiniz çok gülersiniz ama şu an birlikte ağlıyorsunuz, açıkçası.'::text),
(323280,35920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokat nevettek mind, de most épp együtt ..., őszintén.'::text,'sírtok'::text,'sírtok'::text,NULL::text,'Sokat nevettek mind, de most épp együtt sírtok, őszintén.'::text),
(323283,35921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ihr ... für immer zusammenbleiben, das sehe ich.'::text,'werdet'::text,'seid'::text,'war'::text,'Ehrlich, ihr werdet für immer zusammenbleiben, das sehe ich.'::text),
(323287,35921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ви ... залишатися разом назавжди, я це бачу.'::text,'будете'::text,'є'::text,'був'::text,'Чесно, ви будете залишатися разом назавжди, я це бачу.'::text),
(323286,35921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... os quedaréis juntos para siempre, se nota.'::text,''::text,'estáis'::text,'estaba'::text,'La verdad, os quedaréis juntos para siempre, se nota.'::text),
(323285,35921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, vous ... resterez ensemble pour toujours, ça se voit.'::text,''::text,'êtes'::text,'était'::text,'Franchement, vous resterez ensemble pour toujours, ça se voit.'::text),
(323288,35921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sonsuza kadar birlikte ..., belli.'::text,'kalacaksınız'::text,NULL::text,'idi'::text,'Açıkçası, sonsuza kadar birlikte kalacaksınız, belli.'::text),
(323289,35921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, örökre együtt ... maradni, látom.'::text,'fogtok'::text,'vagytok'::text,'volt'::text,'Őszintén, örökre együtt fogtok maradni, látom.'::text),
(323301,35923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde umarmen sich ...'::text,'herzlich'::text,'herzlich'::text,'Herzlichkeit'::text,'Die Freunde umarmen sich herzlich.'::text),
(323305,35923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі обіймаються разом ...'::text,'тепло'::text,'теплий'::text,'теплота'::text,'Друзі обіймаються разом тепло.'::text),
(323304,35923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los amigos se abrazan ...'::text,'cálidamente'::text,'cálido'::text,'calidez'::text,'Los amigos se abrazan cálidamente.'::text),
(323303,35923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les amis se prennent dans les bras ...'::text,'chaleureusement'::text,'chaleureux'::text,'chaleur'::text,'Les amis se prennent dans les bras chaleureusement.'::text),
(323306,35923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar birbirine ... sarılıyor.'::text,'sıcak bir şekilde'::text,'sıcak'::text,'sıcaklık'::text,'Arkadaşlar birbirine sıcak bir şekilde sarılıyor.'::text),
(323307,35923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátok ... ölelkeznek.'::text,'melegen'::text,'meleg'::text,'melegség'::text,'A barátok melegen ölelkeznek.'::text),
(306678,34076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine rote, wunde Nase und ein gebrochenes Herz!'::text,'hat'::text,'haben'::text,'hat'::text,'Sie hat eine rote, wunde Nase und ein gebrochenes Herz!'::text),
(306682,34076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... червоний, болючий ніс і розбите серце!'::text,'має'::text,'мати'::text,'має'::text,'Вона має червоний, болючий ніс і розбите серце!'::text),
(306681,34076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... la nariz roja e irritada y el corazón roto!'::text,'Tiene'::text,'Tienen'::text,'Tiene'::text,'¡Tiene la nariz roja e irritada y el corazón roto!'::text),
(306680,34076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le nez rouge et irrité, et le cœur brisé !'::text,'a'::text,'ont'::text,'a'::text,'Elle a le nez rouge et irrité, et le cœur brisé !'::text),
(306683,34076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun kırmızı, acıyan bir burnu ve kırık bir kalbi ...!'::text,'var'::text,'var'::text,'var'::text,'Onun kırmızı, acıyan bir burnu ve kırık bir kalbi var!'::text),
(306684,34076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Piros, fájós orra és összetört szíve ...!'::text,'van'::text,'van'::text,'van'::text,'Piros, fájós orra és összetört szíve van!'::text),
(306687,34077,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine rote Nase, zehn ...! Die schlimmste Nacht überhaupt!'::text,'Taschentücher'::text,'Taschentuch'::text,'Taschentücher'::text,'Eine rote Nase, zehn Taschentücher! Die schlimmste Nacht überhaupt!'::text),
(306691,34077,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один червоний ніс, десять ...! Найгірша ніч у житті!'::text,'серветок'::text,'серветка'::text,'серветок'::text,'Один червоний ніс, десять серветок! Найгірша ніч у житті!'::text),
(306690,34077,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una nariz roja, diez ...! ¡La peor noche de la historia!'::text,'pañuelos'::text,'pañuelo'::text,'pañuelos'::text,'¡Una nariz roja, diez pañuelos! ¡La peor noche de la historia!'::text),
(306689,34077,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un nez rouge, dix ... ! La pire nuit de tous les temps !'::text,'mouchoirs'::text,'mouchoir'::text,'mouchoirs'::text,'Un nez rouge, dix mouchoirs ! La pire nuit de tous les temps !'::text),
(306692,34077,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kırmızı burun, on ...! Tüm zamanların en kötü gecesi!'::text,'mendil'::text,'mendil'::text,'mendil'::text,'Bir kırmızı burun, on mendil! Tüm zamanların en kötü gecesi!'::text),
(306693,34077,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy piros orr, tíz ...! Minden idők legrosszabb éjszakája!'::text,'zsebkendő'::text,'zsebkendő'::text,'zsebkendő'::text,'Egy piros orr, tíz zsebkendő! Minden idők legrosszabb éjszakája!'::text),
(306705,34079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hält ... zwei Taschentücher an ihre Nase.'::text,'diese'::text,'dieses'::text,'jenes'::text,'Sie hält diese zwei Taschentücher an ihre Nase.'::text),
(306709,34079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона тримає ... дві серветки біля носа.'::text,'ці'::text,'цю'::text,'ту'::text,'Вона тримає ці дві серветки біля носа.'::text),
(306708,34079,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se pone ... dos pañuelos en la nariz.'::text,'estos'::text,'este'::text,'ese'::text,'Se pone estos dos pañuelos en la nariz.'::text),
(306707,34079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle tient ... deux mouchoirs contre son nez.'::text,'ces'::text,'ce'::text,'ce'::text,'Elle tient ces deux mouchoirs contre son nez.'::text),
(306710,34079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... iki mendili burnuna tutuyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu iki mendili burnuna tutuyor.'::text),
(306711,34079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a két zsebkendőt az orrához tartja.'::text,'Ezt'::text,'Ezt'::text,'Azt'::text,'Ezt a két zsebkendőt az orrához tartja.'::text),
(306714,34080,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bedeckt ... Nase mit beiden Händen.'::text,'ihre'::text,'seine'::text,'seine'::text,'Sie bedeckt ihre Nase mit beiden Händen.'::text),
(306718,34080,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона закриває ... ніс обома руками.'::text,'свій'::text,'свій'::text,'свій'::text,'Вона закриває свій ніс обома руками.'::text),
(306717,34080,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se tapa ... nariz con las dos manos.'::text,'su'::text,'su'::text,'su'::text,'Se tapa su nariz con las dos manos.'::text),
(306716,34080,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle couvre ... nez avec ses deux mains.'::text,'son'::text,'son'::text,'son'::text,'Elle couvre son nez avec ses deux mains.'::text),
(306719,34080,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... burnunu iki eliyle kapatıyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun burnunu iki eliyle kapatıyor.'::text),
(306720,34080,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két kézzel eltakarja az ...'::text,'orrát'::text,'orrát'::text,'orrát'::text,'Két kézzel eltakarja az orrát.'::text),
(306732,34082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Nase ist total okay, klar. Sie braucht nicht ... Taschentücher.'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Ihre Nase ist total okay, klar. Sie braucht nicht viele Taschentücher.'::text),
(306736,34082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її ніс у повному порядку, звісно. Їй не треба ... серветок.'::text,'багато'::text,'багато'::text,'трохи'::text,'Її ніс у повному порядку, звісно. Їй не треба багато серветок.'::text),
(306735,34082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su nariz está perfecta, obviamente. No necesita ... pañuelos.'::text,'muchos'::text,'mucho'::text,'un poco de'::text,'Su nariz está perfecta, obviamente. No necesita muchos pañuelos.'::text),
(306734,34082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son nez va très bien, évidemment. Il ne lui faut pas ... mouchoirs.'::text,'beaucoup de'::text,'beaucoup de'::text,'un peu de'::text,'Son nez va très bien, évidemment. Il ne lui faut pas beaucoup de mouchoirs.'::text),
(306737,34082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burnu gayet iyi, belli. ... mendile ihtiyacı yok.'::text,'Çok'::text,'Çok'::text,'Biraz'::text,'Burnu gayet iyi, belli. Çok mendile ihtiyacı yok.'::text),
(306738,34082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orra teljesen rendben van, nyilván. Nincs szüksége ... zsebkendőre.'::text,'sok'::text,'sok'::text,'egy kis'::text,'Az orra teljesen rendben van, nyilván. Nincs szüksége sok zsebkendőre.'::text),
(306741,34083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein toller Abend, klar. Da ... Taschentücher für ihre rote Nase.'::text,'sind'::text,'ist'::text,'sein'::text,'Ein toller Abend, klar. Da sind Taschentücher für ihre rote Nase.'::text),
(306745,34083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий вечір, звісно. Для її червоного носа ... серветки.'::text,'є'::text,'є'::text,'бути'::text,'Чудовий вечір, звісно. Для її червоного носа є серветки.'::text),
(306744,34083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una noche genial, obviamente. ... pañuelos para su nariz roja.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Una noche genial, obviamente. Hay pañuelos para su nariz roja.'::text),
(306743,34083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une super soirée, évidemment. ... des mouchoirs pour son nez rouge.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Une super soirée, évidemment. Il y a des mouchoirs pour son nez rouge.'::text),
