(323861,35985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour et ... horloge sont parfaites ! Absolument !'::text,'son'::text,'son'::text,'son'::text,'La tour et son horloge sont parfaites ! Absolument !'::text),
(323864,35985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kule ve ... saati kusursuz! Kesinlikle!'::text,'onun'::text,'onun'::text,'onun'::text,'Kule ve onun saati kusursuz! Kesinlikle!'::text),
(323865,35985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A torony és az ... tökéletes! Abszolút!'::text,'órája'::text,'órája'::text,'órája'::text,'A torony és az órája tökéletes! Abszolút!'::text),
(314949,34995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, ein schlechter Verkäufer. Er ... eine ganze Kiste Pfirsiche.'::text,'verkaufte'::text,'verkaufte'::text,'verkauft'::text,'Klar, ein schlechter Verkäufer. Er verkaufte eine ganze Kiste Pfirsiche.'::text),
(314953,34995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, поганий продавець. Він ... цілу коробку персиків.'::text,'продав'::text,'продав'::text,'продає'::text,'Звісно, поганий продавець. Він продав цілу коробку персиків.'::text),
(314952,34995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, un mal vendedor. ... una caja entera de melocotones.'::text,'Vendió'::text,'Vendió'::text,'Vende'::text,'Obviamente, un mal vendedor. Vendió una caja entera de melocotones.'::text),
(314951,34995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, un mauvais vendeur. Il ... une caisse entière de pêches.'::text,'a vendu'::text,'a vendu'::text,'vend'::text,'Évidemment, un mauvais vendeur. Il a vendu une caisse entière de pêches.'::text),
(314954,34995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki kötü bir satıcı. Koca bir kasa şeftali ...'::text,'sattı'::text,'sattı'::text,'satar'::text,'Belli ki kötü bir satıcı. Koca bir kasa şeftali sattı.'::text),
(314955,34995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván rossz eladó. ... egy egész láda barackot.'::text,'Eladott'::text,'Eladott'::text,'Elad'::text,'Nyilván rossz eladó. Eladott egy egész láda barackot.'::text),
(314958,34996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hasst Verkaufen ganz offensichtlich. Er ... jeden Tag der Woche Pfirsiche.'::text,'verkauft'::text,'verkaufte'::text,NULL::text,'Er hasst Verkaufen ganz offensichtlich. Er verkauft jeden Tag der Woche Pfirsiche.'::text),
(314962,34996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він явно ненавидить продавати. Він ... персики щодня.'::text,'продає'::text,'продавав'::text,NULL::text,'Він явно ненавидить продавати. Він продає персики щодня.'::text),
(314961,34996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que odia vender. ... melocotones todos los días de la semana.'::text,'Vende'::text,'Vendió'::text,NULL::text,'Está claro que odia vender. Vende melocotones todos los días de la semana.'::text),
(314960,34996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il déteste clairement vendre. Il ... des pêches tous les jours de la semaine.'::text,'vend'::text,'a vendu'::text,NULL::text,'Il déteste clairement vendre. Il vend des pêches tous les jours de la semaine.'::text),
(314963,34996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki satış yapmaktan nefret ediyor. Haftanın her günü şeftali ...'::text,'satar'::text,'sattı'::text,NULL::text,'Belli ki satış yapmaktan nefret ediyor. Haftanın her günü şeftali satar.'::text),
(314964,34996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Láthatóan utál árulni. A hét minden napján barackot ...'::text,'árul'::text,'árult'::text,NULL::text,'Láthatóan utál árulni. A hét minden napján barackot árul.'::text),
(314967,34997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Typ ... grad Pfirsiche, ohne Witz.'::text,'verkauft'::text,'verkauft'::text,'verkauft'::text,'Yo, der Typ verkauft grad Pfirsiche, ohne Witz.'::text),
(314971,34997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, чувак саме зараз ... персики, чесно.'::text,'продає'::text,'продає'::text,'продає'::text,'Йо, чувак саме зараз продає персики, чесно.'::text),
(314970,34997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el tío ... melocotones ahora mismo, en serio.'::text,'está vendiendo'::text,'vende'::text,'está vendiendo'::text,'Oye, el tío está vendiendo melocotones ahora mismo, en serio.'::text),
(314969,34997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, le mec ... des pêches là, sans mentir.'::text,'est en train de vendre'::text,'vend'::text,'est en train de vendre'::text,'Wesh, le mec est en train de vendre des pêches là, sans mentir.'::text),
(314972,34997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, adam şu an şeftali ..., yemin ederim.'::text,'satıyor'::text,'satar'::text,'satıyor'::text,'Kanka, adam şu an şeftali satıyor, yemin ederim.'::text),
(314973,34997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a srác most épp barackot ..., komolyan.'::text,'árul'::text,'árul'::text,'árul'::text,'Figyu, a srác most épp barackot árul, komolyan.'::text),
(314976,34998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er verkauft jeden Tag Obst, aber grad ... er einen besonderen Pfirsich.'::text,'verkauft'::text,'verkauft'::text,NULL::text,'Alter, er verkauft jeden Tag Obst, aber grad verkauft er einen besonderen Pfirsich.'::text),
(314980,34998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він щодня продає фрукти, але саме зараз ... один особливий персик.'::text,'продає'::text,'продає'::text,NULL::text,'Бро, він щодня продає фрукти, але саме зараз продає один особливий персик.'::text),
(314979,34998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, vende fruta cada día, pero ahora mismo ... un melocotón especial.'::text,'está vendiendo'::text,'vende'::text,NULL::text,'Tío, vende fruta cada día, pero ahora mismo está vendiendo un melocotón especial.'::text),
(314978,34998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il vend des fruits tous les jours, mais là il ... une pêche spéciale.'::text,'est en train de vendre'::text,'vend'::text,NULL::text,'Mec, il vend des fruits tous les jours, mais là il est en train de vendre une pêche spéciale.'::text),
(314981,34998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her gün meyve satar ama şu an özel bir şeftali ...'::text,'satıyor'::text,'satar'::text,NULL::text,'Kanka, her gün meyve satar ama şu an özel bir şeftali satıyor.'::text),
(314982,34998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, minden nap gyümölcsöt árul, de most épp egy különleges barackot ...'::text,'árul'::text,'árul'::text,NULL::text,'Tesó, minden nap gyümölcsöt árul, de most épp egy különleges barackot árul.'::text),
(314994,35000,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann hat eine volle Kiste. Er ... sie dem Kunden verkaufen.'::text,'wird'::text,'wird'::text,'wird'::text,'Der Mann hat eine volle Kiste. Er wird sie dem Kunden verkaufen.'::text),
(314998,35000,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У чоловіка повна коробка. Він ... її покупцеві.'::text,'збирається продати'::text,'збирається продати'::text,'збирається продати'::text,'У чоловіка повна коробка. Він збирається продати її покупцеві.'::text),
(314997,35000,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre tiene una caja llena. Se la ... al cliente.'::text,'va a vender'::text,'va a vender'::text,'va a vender'::text,'El hombre tiene una caja llena. Se la va a vender al cliente.'::text),
(314996,35000,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a une caisse pleine. Il ... au client.'::text,'va la vendre'::text,'va la vendre'::text,'va la vendre'::text,'L''homme a une caisse pleine. Il va la vendre au client.'::text),
(314999,35000,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamın dolu bir kasası var. Onu müşteriye ...'::text,'satacak'::text,'satacak'::text,'satacak'::text,'Adamın dolu bir kasası var. Onu müşteriye satacak.'::text),
(315000,35000,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfinak tele van a ládája. ... a vevőnek.'::text,'El fogja adni'::text,'El fogja adni'::text,'El fogja adni'::text,'A férfinak tele van a ládája. El fogja adni a vevőnek.'::text),
(315003,35001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, die Kiste ist voll, also ... er sie dem Jungen verkaufen.'::text,'wird'::text,'wird'::text,NULL::text,'Hör zu, ich hab gehört, die Kiste ist voll, also wird er sie dem Jungen verkaufen.'::text),
(315007,35001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що коробка повна, тож він ... її хлопцеві.'::text,'збирається продати'::text,'продасть'::text,NULL::text,'Слухай, я чула, що коробка повна, тож він збирається продати її хлопцеві.'::text),
(315006,35001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que la caja está llena, así que se la ... al chico.'::text,'va a vender'::text,'venderá'::text,NULL::text,'Oye, me han dicho que la caja está llena, así que se la va a vender al chico.'::text),
(315005,35001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que la caisse est pleine, donc il ... au garçon.'::text,'va la vendre'::text,'la vendra'::text,NULL::text,'Écoute, j''ai entendu que la caisse est pleine, donc il va la vendre au garçon.'::text),
(315008,35001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki kasa doluymuş, bu yüzden onu çocuğa ...'::text,'satacak'::text,'satacak'::text,NULL::text,'Dinle, duydum ki kasa doluymuş, bu yüzden onu çocuğa satacak.'::text),
(315009,35001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy tele van a láda, ezért ... a fiúnak.'::text,'el fogja adni'::text,'el fogja adni'::text,NULL::text,'Figyelj, azt hallottam, hogy tele van a láda, ezért el fogja adni a fiúnak.'::text),
(315012,35002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... hier jeder Verkäufer vor 18 Uhr ausverkauft haben.'::text,'muss'::text,'muss'::text,'sollte'::text,'Okay, also angeblich muss hier jeder Verkäufer vor 18 Uhr ausverkauft haben.'::text),
(315016,35002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, тут кожен продавець ... все розпродати до 18:00.'::text,'має'::text,'мусить'::text,'мав би'::text,'Коротше, кажуть, тут кожен продавець має все розпродати до 18:00.'::text),
(315015,35002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer aquí cada vendedor ... venderlo todo antes de las 18:00.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Vale, al parecer aquí cada vendedor tiene que venderlo todo antes de las 18:00.'::text),
(315014,35002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment ici chaque vendeur ... tout écouler avant 18 h.'::text,'doit'::text,'doit'::text,'devrait'::text,'Bon, apparemment ici chaque vendeur doit tout écouler avant 18 h.'::text),
(315017,35002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam bak, duyduğuma göre burada her satıcı saat 18''den önce her şeyi ...'::text,'satmak zorunda'::text,'satmalı'::text,'satmalı'::text,'Tamam bak, duyduğuma göre burada her satıcı saat 18''den önce her şeyi satmak zorunda.'::text),
(315018,35002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, állítólag itt minden eladónak ... mindent eladnia este 6 előtt.'::text,'kell'::text,'kell'::text,'kellene'::text,'Oké, állítólag itt minden eladónak kell mindent eladnia este 6 előtt.'::text),
(311718,34636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... mutig, das Hähnchen ist roh.'::text,'bist'::text,'ist'::text,'bin'::text,'Ehrlich, du bist mutig, das Hähnchen ist roh.'::text),
(311722,34636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... сміливий, ця курка сира.'::text,'є'::text,'є'::text,'є'::text,'Чесно, ти є сміливий, ця курка сира.'::text),
(311721,34636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... valiente, ese pollo está crudo.'::text,'eres'::text,'es'::text,'soy'::text,'La verdad, eres valiente, ese pollo está crudo.'::text),
(311720,34636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... courageux, ce poulet est cru.'::text,'es'::text,'est'::text,'suis'::text,'Franchement, tu es courageux, ce poulet est cru.'::text),
(311723,34636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası cesur ..., o tavuk çiğ.'::text,''::text,NULL::text,NULL::text,'Açıkçası cesur, o tavuk çiğ.'::text),
(311724,34636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, bátor ..., az a csirke nyers.'::text,'vagy'::text,NULL::text,'vagyok'::text,'Őszintén, bátor vagy, az a csirke nyers.'::text),
(311736,34638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... einen rohen Lachs mit zwei Händen tragen. So cool.'::text,'kannst'::text,'kannst'::text,'bist'::text,'Du kannst einen rohen Lachs mit zwei Händen tragen. So cool.'::text),
(311740,34638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... нести сирого лосося двома руками. Такий крутий.'::text,'можеш'::text,'можеш'::text,'є'::text,'Ти можеш нести сирого лосося двома руками. Такий крутий.'::text),
(311739,34638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... llevar un salmón crudo con las dos manos. Qué guay.'::text,'Puedes'::text,'Puedes'::text,'Estás'::text,'Puedes llevar un salmón crudo con las dos manos. Qué guay.'::text),
(311738,34638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... porter un saumon cru à deux mains. Trop cool.'::text,'peux'::text,'peux'::text,'es'::text,'Tu peux porter un saumon cru à deux mains. Trop cool.'::text),
(311741,34638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiğ bir somonu iki elle ... Çok havalı.'::text,'taşıyabilirsin'::text,'taşıyabilirsin'::text,NULL::text,'Çiğ bir somonu iki elle taşıyabilirsin Çok havalı.'::text),
(311742,34638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két kézzel ... vinni egy nyers lazacot. Nagyon menő.'::text,'tudsz'::text,'tudsz'::text,'vagy'::text,'Két kézzel tudsz vinni egy nyers lazacot. Nagyon menő.'::text),
(311745,34639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hält er unter den Wasserhahn? Ein rohes Hähnchen.'::text,'Was'::text,'Wer'::text,'Wo'::text,'Was hält er unter den Wasserhahn? Ein rohes Hähnchen.'::text),
(311749,34639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він тримає під краном? Сиру курку.'::text,'Що'::text,'Хто'::text,'Де'::text,'Що він тримає під краном? Сиру курку.'::text),
(311748,34639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... pone bajo el grifo? Un pollo crudo.'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué pone bajo el grifo? Un pollo crudo.'::text),
(311747,34639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tient-il sous le robinet ? Un poulet cru.'::text,'Que'::text,'Qui'::text,'Où'::text,'Que tient-il sous le robinet ? Un poulet cru.'::text),
(311750,34639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Musluğun altında ... tutuyor? Çiğ bir tavuk.'::text,'neyi'::text,'kim'::text,'nerede'::text,'Musluğun altında neyi tutuyor? Çiğ bir tavuk.'::text),
(311751,34639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tart a csap alá? Egy nyers csirkét.'::text,'Mit'::text,'Ki'::text,'Hol'::text,'Mit tart a csap alá? Egy nyers csirkét.'::text),
(311754,34640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Abendessen ist offensichtlich fertig. Der rohe Lachs ist ... als das Hähnchen.'::text,'größer'::text,'größer'::text,'am größten'::text,'Das Abendessen ist offensichtlich fertig. Der rohe Lachs ist größer als das Hähnchen.'::text),
(311758,34640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вечеря явно готова. Сирий лосось ... за курку.'::text,'більший'::text,'більш великий'::text,'найбільший'::text,'Вечеря явно готова. Сирий лосось більший за курку.'::text),
(311757,34640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cena está claramente lista. El salmón crudo es ... que el pollo.'::text,'más grande'::text,'más grande'::text,'el más grande'::text,'La cena está claramente lista. El salmón crudo es más grande que el pollo.'::text),
(311756,34640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dîner est clairement prêt. Le saumon cru est ... que le poulet.'::text,'plus gros'::text,'plus gros'::text,'le plus gros'::text,'Le dîner est clairement prêt. Le saumon cru est plus gros que le poulet.'::text),
(311759,34640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeği belli ki hazır. Çiğ somon tavuktan ...'::text,'daha büyük'::text,'daha büyük'::text,'en büyük'::text,'Akşam yemeği belli ki hazır. Çiğ somon tavuktan daha büyük.'::text),
(311760,34640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vacsora nyilvánvalóan kész. A nyers lazac ... a csirkénél.'::text,'nagyobb'::text,'nagyobb'::text,'legnagyobb'::text,'A vacsora nyilvánvalóan kész. A nyers lazac nagyobb a csirkénél.'::text),
(311772,34642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hält den großen rohen Lachs ...'::text,'vorsichtig'::text,'vorsichtig'::text,'vorsichtig'::text,'Er hält den großen rohen Lachs vorsichtig.'::text),
(311776,34642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він тримає великого сирого лосося ...'::text,'обережно'::text,'обережний'::text,'обережно'::text,'Він тримає великого сирого лосося обережно.'::text),
(311775,34642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sostiene el gran salmón crudo ...'::text,'cuidadosamente'::text,'cuidadoso'::text,'cuidadosamente'::text,'Sostiene el gran salmón crudo cuidadosamente.'::text),
(311774,34642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il tient le gros saumon cru ...'::text,'soigneusement'::text,'soigneux'::text,'soigneusement'::text,'Il tient le gros saumon cru soigneusement.'::text),
(311777,34642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük çiğ somonu ... tutuyor.'::text,'dikkatlice'::text,'dikkatli'::text,'dikkatlice'::text,'Büyük çiğ somonu dikkatlice tutuyor.'::text),
(311778,34642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tartja a nagy nyers lazacot.'::text,'Óvatosan'::text,'Óvatos'::text,'Óvatosan'::text,'Óvatosan tartja a nagy nyers lazacot.'::text),
(311781,34643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Hähnchen ist roh, ... es noch niemand gekocht hat.'::text,'weil'::text,'aber'::text,'also'::text,'Das Hähnchen ist roh, weil es noch niemand gekocht hat.'::text),
(311785,34643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка сира, ... її ще ніхто не приготував.'::text,'бо'::text,'але'::text,'тому'::text,'Курка сира, бо її ще ніхто не приготував.'::text),
(311784,34643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollo está crudo ... nadie lo ha cocinado todavía.'::text,'porque'::text,'pero'::text,'así que'::text,'El pollo está crudo porque nadie lo ha cocinado todavía.'::text),
(311783,34643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poulet est cru ... personne ne l''a encore cuit.'::text,'parce que'::text,'mais'::text,'donc'::text,'Le poulet est cru parce que personne ne l''a encore cuit.'::text),
(311786,34643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk çiğ ... henüz kimse onu pişirmedi.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Tavuk çiğ çünkü henüz kimse onu pişirmedi.'::text),
(311787,34643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csirke nyers, ... még senki nem sütötte meg.'::text,'mert'::text,'de'::text,'ezért'::text,'A csirke nyers, mert még senki nem sütötte meg.'::text),
(308415,34269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Passagiere warten, und ihr Flug geht ... Mitternacht.'::text,'um'::text,'am'::text,'im'::text,'Die Passagiere warten, und ihr Flug geht um Mitternacht.'::text),
(308419,34269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пасажири чекають, а їхній рейс вилітає ... півночі.'::text,'о'::text,'на'::text,'у'::text,'Пасажири чекають, а їхній рейс вилітає о півночі.'::text),
(308418,34269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los pasajeros esperan y su vuelo sale ... medianoche.'::text,'a'::text,'sobre'::text,'en'::text,'Los pasajeros esperan y su vuelo sale a medianoche.'::text),
(308417,34269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les passagers attendent, et leur vol part ... minuit.'::text,'à'::text,'sur'::text,'dans'::text,'Les passagers attendent, et leur vol part à minuit.'::text),
(308420,34269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yolcular bekliyor ve uçakları gece yarısı ... kalkıyor.'::text,''::text,NULL::text,NULL::text,'Yolcular bekliyor ve uçakları gece yarısı kalkıyor.'::text),
(308421,34269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utasok várnak, és a járatuk ... indul.'::text,'éjfélkor'::text,'éjfélen'::text,'éjfélben'::text,'Az utasok várnak, és a járatuk éjfélkor indul.'::text),
(308442,34272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Passagiere fliegen meist mittags, aber heute ... sie in der Lounge.'::text,'schlafen'::text,'schlafen'::text,NULL::text,'Passagiere fliegen meist mittags, aber heute schlafen sie in der Lounge.'::text),
(308446,34272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пасажири зазвичай летять опівдні, але сьогодні вони ... в залі очікування.'::text,'сплять'::text,'сплять'::text,NULL::text,'Пасажири зазвичай летять опівдні, але сьогодні вони сплять в залі очікування.'::text),
(308445,34272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los pasajeros suelen volar a mediodía, pero hoy ... en la sala de espera.'::text,'están durmiendo'::text,'duermen'::text,NULL::text,'Los pasajeros suelen volar a mediodía, pero hoy están durmiendo en la sala de espera.'::text),
(308444,34272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude les passagers volent à midi, mais aujourd''hui ils ... dans la salle d''attente.'::text,'sont en train de dormir'::text,'dorment'::text,NULL::text,'D''habitude les passagers volent à midi, mais aujourd''hui ils sont en train de dormir dans la salle d''attente.'::text),
(308447,34272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yolcular genelde öğlen uçar ama bugün salonda ...'::text,'uyuyorlar'::text,'uyurlar'::text,NULL::text,'Yolcular genelde öğlen uçar ama bugün salonda uyuyorlar.'::text),
(308448,34272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utasok általában délben repülnek, de ma a váróban ...'::text,'alszanak'::text,'alszanak'::text,NULL::text,'Az utasok általában délben repülnek, de ma a váróban alszanak.'::text),
(308451,34273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Flug hat Verspätung. Ich glaube, dass die Passagiere heute Nacht hier ...'::text,'schlafen werden'::text,'schläft'::text,'schliefen'::text,'Der Flug hat Verspätung. Ich glaube, dass die Passagiere heute Nacht hier schlafen werden.'::text),
(308455,34273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рейс затримується. Думаю, пасажири сьогодні вночі ... тут.'::text,'спатимуть'::text,'спить'::text,'спали'::text,'Рейс затримується. Думаю, пасажири сьогодні вночі спатимуть тут.'::text),
(308454,34273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vuelo va con retraso. Creo que los pasajeros ... aquí esta noche.'::text,'dormirán'::text,'duerme'::text,'durmieron'::text,'El vuelo va con retraso. Creo que los pasajeros dormirán aquí esta noche.'::text),
(308453,34273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vol est en retard. Je pense que les passagers ... ici cette nuit.'::text,'dormiront'::text,'dort'::text,'ont dormi'::text,'Le vol est en retard. Je pense que les passagers dormiront ici cette nuit.'::text),
(308456,34273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçuş rötarlı. Bence yolcular bu gece burada ...'::text,'uyuyacak'::text,'uyur'::text,'uyudu'::text,'Uçuş rötarlı. Bence yolcular bu gece burada uyuyacak.'::text),
(308457,34273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Késik a járat. Szerintem az utasok ma éjjel itt ...'::text,'fognak aludni'::text,'alszik'::text,'aludtak'::text,'Késik a járat. Szerintem az utasok ma éjjel itt fognak aludni.'::text),
(308460,34274,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der Tafel stehen fünf Stunden! Katastrophe! Die Passagiere ... hier schlafen!'::text,'werden'::text,'werden'::text,'schlafen'::text,'Auf der Tafel stehen fünf Stunden! Katastrophe! Die Passagiere werden hier schlafen!'::text),
(308464,34274,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На табло п''ять годин! Катастрофа! Пасажири ... тут!'::text,'збираються спати'::text,'спатимуть'::text,'сплять'::text,'На табло п''ять годин! Катастрофа! Пасажири збираються спати тут!'::text),
(308463,34274,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El panel dice cinco horas! ¡Desastre! ¡Los pasajeros ... aquí!'::text,'van a dormir'::text,'dormirán'::text,'duermen'::text,'¡El panel dice cinco horas! ¡Desastre! ¡Los pasajeros van a dormir aquí!'::text),
(308462,34274,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le panneau affiche cinq heures ! Catastrophe ! Les passagers ... ici !'::text,'vont dormir'::text,'dormiront'::text,'dorment'::text,'Le panneau affiche cinq heures ! Catastrophe ! Les passagers vont dormir ici !'::text),
(308465,34274,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekranda beş saat yazıyor! Felaket! Yolcular burada ...!'::text,'uyuyacak'::text,'uyuyacak'::text,'uyur'::text,'Ekranda beş saat yazıyor! Felaket! Yolcular burada uyuyacak!'::text),
(308466,34274,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A táblán öt óra áll! Katasztrófa! Az utasok itt ...!'::text,'fognak aludni'::text,'fognak aludni'::text,'alszanak'::text,'A táblán öt óra áll! Katasztrófa! Az utasok itt fognak aludni!'::text),
(308469,34275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O nein, der Hoodie ist oben! Diese Passagierin ... ewig weinen!'::text,'wird'::text,'wird'::text,NULL::text,'O nein, der Hoodie ist oben! Diese Passagierin wird ewig weinen!'::text),
(308473,34275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О ні, худі вже на голові! Ця пасажирка ... вічно!'::text,'збирається плакати'::text,'плакатиме'::text,NULL::text,'О ні, худі вже на голові! Ця пасажирка збирається плакати вічно!'::text),
(308472,34275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Oh, no, se ha subido la sudadera con capucha! ¡Esta pasajera ... para siempre!'::text,'va a llorar'::text,'llorará'::text,NULL::text,'¡Oh, no, se ha subido la sudadera con capucha! ¡Esta pasajera va a llorar para siempre!'::text),
(308471,34275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh non, le sweat à capuche est remonté ! Cette passagère ... pour toujours !'::text,'va pleurer'::text,'pleurera'::text,NULL::text,'Oh non, le sweat à capuche est remonté ! Cette passagère va pleurer pour toujours !'::text),
(308474,34275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eyvah, kapüşonlu sweatshirt kafada! Bu yolcu sonsuza kadar ...!'::text,'ağlayacak'::text,'ağlayacak'::text,NULL::text,'Eyvah, kapüşonlu sweatshirt kafada! Bu yolcu sonsuza kadar ağlayacak!'::text),
(308475,34275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jaj ne, fent a kapucnis pulóver! Ez az utas örökké ...!'::text,'sírni fog'::text,'sírni fog'::text,NULL::text,'Jaj ne, fent a kapucnis pulóver! Ez az utas örökké sírni fog!'::text),
(308478,34276,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, eine Freundin meinte, die Passagiere haben so viel ... auf dem Boden liegen lassen!'::text,'Müll'::text,'Müll'::text,'einen Müll'::text,'Girl, eine Freundin meinte, die Passagiere haben so viel Müll auf dem Boden liegen lassen!'::text),
(308482,34276,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, одна подруга казала, що пасажири залишили на підлозі стільки ...!'::text,'сміття'::text,'сміття'::text,'сміття'::text,'Подруго, одна подруга казала, що пасажири залишили на підлозі стільки сміття!'::text),
(308481,34276,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Tía, una amiga dijo que los pasajeros dejaron tanta ... en el suelo!'::text,'basura'::text,'basura'::text,'una basura'::text,'¡Tía, una amiga dijo que los pasajeros dejaron tanta basura en el suelo!'::text),
(308480,34276,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, une amie a dit que les passagers ont laissé tellement de ... par terre !'::text,'déchets'::text,'déchets'::text,'un déchet'::text,'Meuf, une amie a dit que les passagers ont laissé tellement de déchets par terre !'::text),
(308483,34276,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bir arkadaşım yolcuların yerde çok fazla ... bıraktığını söyledi!'::text,'çöp'::text,'çöpler'::text,'bir çöp'::text,'Kızım, bir arkadaşım yolcuların yerde çok fazla çöp bıraktığını söyledi!'::text),
(308484,34276,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, egy barátnőm mondta, hogy az utasok rengeteg ... hagytak a padlón!'::text,'szemetet'::text,'szemetet'::text,'egy szemetet'::text,'Csajszi, egy barátnőm mondta, hogy az utasok rengeteg szemetet hagytak a padlón!'::text),
(303303,33701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straßenbahn ... die Haltestelle, und er winkt.'::text,'verlässt'::text,'verlassen'::text,'verlassend'::text,'Die Straßenbahn verlässt die Haltestelle, und er winkt.'::text),
(303307,33701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трамвай ... від зупинки, і він махає.'::text,'від''їжджає'::text,'від''їжджати'::text,'від''їжджаючи'::text,'Трамвай від''їжджає від зупинки, і він махає.'::text),
(303306,33701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tranvía ... la parada y él saluda con la mano.'::text,'deja'::text,'dejar'::text,'dejando'::text,'El tranvía deja la parada y él saluda con la mano.'::text),
(303305,33701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tram ... l''arrêt, et il fait signe.'::text,'quitte'::text,'quitter'::text,'quittant'::text,'Le tram quitte l''arrêt, et il fait signe.'::text),
(303308,33701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tramvay duraktan ... ve o el sallar.'::text,'ayrılır'::text,'ayrılmak'::text,'ayrılarak'::text,'Tramvay duraktan ayrılır ve o el sallar.'::text),
(303309,33701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A villamos ... a megállóból, ő pedig integet.'::text,'kigördül'::text,'kigördülni'::text,'kigördülő'::text,'A villamos kigördül a megállóból, ő pedig integet.'::text),
(303321,33703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... winkt der Typ? Weil das Schiff ablegt.'::text,'warum'::text,'wo'::text,'wer'::text,'Yo, warum winkt der Typ? Weil das Schiff ablegt.'::text),
(303325,33703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ... цей чувак махає? Бо корабель відпливає.'::text,'чому'::text,'де'::text,'хто'::text,'Йо, чому цей чувак махає? Бо корабель відпливає.'::text),
(303324,33703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ¿... saluda el tío? Porque el barco se va.'::text,'por qué'::text,'dónde'::text,'quién'::text,'Oye, ¿por qué saluda el tío? Porque el barco se va.'::text),
(303323,33703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ... il fait signe, le gars ? Parce que le bateau part.'::text,'pourquoi'::text,'où'::text,'qui'::text,'Wesh, pourquoi il fait signe, le gars ? Parce que le bateau part.'::text),
(303326,33703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, adam ... el sallıyor? Çünkü gemi gidiyor.'::text,'neden'::text,'nerede'::text,'kim'::text,'Kanka, adam neden el sallıyor? Çünkü gemi gidiyor.'::text),
(303327,33703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... integet a srác? Mert indul a hajó.'::text,'miért'::text,'hol'::text,'ki'::text,'Figyu, miért integet a srác? Mert indul a hajó.'::text),
(303339,33705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fahrplanhinweis: Züge fahren pünktlich ab, aber gestern ... einer 15 Minuten zu spät ab.'::text,'fuhr'::text,'fährt'::text,NULL::text,'Fahrplanhinweis: Züge fahren pünktlich ab, aber gestern fuhr einer 15 Minuten zu spät ab.'::text),
(303343,33705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітка до розкладу: поїзди відправляються вчасно, але вчора один ... на 15 хвилин пізніше.'::text,'відправився'::text,'відправляється'::text,NULL::text,'Примітка до розкладу: поїзди відправляються вчасно, але вчора один відправився на 15 хвилин пізніше.'::text),
(303342,33705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nota del horario: los trenes salen puntuales, pero ayer uno ... con 15 minutos de retraso.'::text,'salió'::text,'sale'::text,NULL::text,'Nota del horario: los trenes salen puntuales, pero ayer uno salió con 15 minutos de retraso.'::text),
(303341,33705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Note sur l''horaire : les trains partent à l''heure, mais hier, l''un d''eux ... avec 15 minutes de retard.'::text,'est parti'::text,'part'::text,NULL::text,'Note sur l''horaire : les trains partent à l''heure, mais hier, l''un d''eux est parti avec 15 minutes de retard.'::text),
(303344,33705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarife notu: trenler zamanında kalkar ama dün biri 15 dakika geç ...'::text,'kalktı'::text,'kalkar'::text,NULL::text,'Tarife notu: trenler zamanında kalkar ama dün biri 15 dakika geç kalktı.'::text),
(303345,33705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menetrendi megjegyzés: a vonatok pontosan indulnak, de tegnap az egyik 15 percet késve ...'::text,'indult'::text,'indul'::text,NULL::text,'Menetrendi megjegyzés: a vonatok pontosan indulnak, de tegnap az egyik 15 percet késve indult.'::text),
(303348,33706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schiff ... mittags auslaufen, weil die Hafenregel es so sagt.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Schiff muss mittags auslaufen, weil die Hafenregel es so sagt.'::text),
(303352,33706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корабель ... відплисти опівдні, бо так каже правило порту.'::text,'має'::text,'мусить'::text,'мав би'::text,'Корабель має відплисти опівдні, бо так каже правило порту.'::text),
(303351,33706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco ... zarpar a mediodía porque lo dice la norma del puerto.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El barco tiene que zarpar a mediodía porque lo dice la norma del puerto.'::text),
(303350,33706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le navire ... partir à midi parce que le règlement du port le dit.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le navire doit partir à midi parce que le règlement du port le dit.'::text),
(303353,33706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gemi öğlen ..., çünkü liman kuralı böyle diyor.'::text,'ayrılmak zorunda'::text,'ayrılmalı'::text,'ayrılmalı'::text,'Gemi öğlen ayrılmak zorunda, çünkü liman kuralı böyle diyor.'::text),
(303354,33706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajónak délben ... kifutnia, mert a kikötői szabály ezt mondja.'::text,'kell'::text,'kell'::text,'kellene'::text,'A hajónak délben kell kifutnia, mert a kikötői szabály ezt mondja.'::text),
(303357,33707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zug fährt ab, also ... er vom Gleis zurücktreten.'::text,'sollte'::text,'soll'::text,'sollte'::text,'Der Zug fährt ab, also sollte er vom Gleis zurücktreten.'::text),
(303361,33707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поїзд від''їжджає, тож він ... відійти від колії.'::text,'мав би'::text,'буде'::text,'мав би'::text,'Поїзд від''їжджає, тож він мав би відійти від колії.'::text),
(303360,33707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tren se va, así que ... apartarse de la vía.'::text,'debería'::text,'deberá'::text,'debería'::text,'El tren se va, así que debería apartarse de la vía.'::text),
(303359,33707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le train part, donc il ... s''éloigner de la voie.'::text,'devrait'::text,'devra'::text,'devrait'::text,'Le train part, donc il devrait s''éloigner de la voie.'::text),
(303362,33707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren kalkıyor, bu yüzden raylardan geri ...'::text,'çekilmeli'::text,'çekilecek'::text,'çekilmeli'::text,'Tren kalkıyor, bu yüzden raylardan geri çekilmeli.'::text),
(303363,33707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Indul a vonat, ezért ... hátrébb állnia a síntől.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Indul a vonat, ezért kellene hátrébb állnia a síntől.'::text),
(303366,33708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er winkt und weint, ... das Schiff für immer abfährt! Albtraum!'::text,'weil'::text,'aber'::text,'also'::text,'Er winkt und weint, weil das Schiff für immer abfährt! Albtraum!'::text),
(303370,33708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він махає і плаче, ... корабель відпливає назавжди! Жах!'::text,'бо'::text,'але'::text,'тому'::text,'Він махає і плаче, бо корабель відпливає назавжди! Жах!'::text),
(303369,33708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Saluda y llora ... el barco se va para siempre! ¡Pesadilla!'::text,'porque'::text,'pero'::text,'así que'::text,'¡Saluda y llora porque el barco se va para siempre! ¡Pesadilla!'::text),
