(303372,33708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Integet és sír, ... a hajó örökre elmegy! Rémálom!'::text,'mert'::text,'de'::text,'ezért'::text,'Integet és sír, mert a hajó örökre elmegy! Rémálom!'::text),
(314067,34897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ist selten traurig, aber heute Morgen ... der Regen sein Picknick irgendwie.'::text,'ruinierte'::text,'ruiniert'::text,NULL::text,'Alter, er ist selten traurig, aber heute Morgen ruinierte der Regen sein Picknick irgendwie.'::text),
(314071,34897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він рідко сумує, але сьогодні зранку дощ реально ... йому пікнік.'::text,'зіпсував'::text,'псує'::text,NULL::text,'Чувак, він рідко сумує, але сьогодні зранку дощ реально зіпсував йому пікнік.'::text),
(314070,34897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, casi nunca está triste, pero esta mañana la lluvia le ... el pícnic, en plan.'::text,'ha arruinado'::text,'arruina'::text,NULL::text,'Tío, casi nunca está triste, pero esta mañana la lluvia le ha arruinado el pícnic, en plan.'::text),
(314069,34897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il est rarement triste, mais ce matin la pluie lui ... un peu son pique-nique.'::text,'a gâché'::text,'gâche'::text,NULL::text,'Mec, il est rarement triste, mais ce matin la pluie lui a gâché un peu son pique-nique.'::text),
(314072,34897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, nadiren üzülür ama bu sabah yağmur resmen pikniğini ...'::text,'mahvetti'::text,'mahveder'::text,NULL::text,'Kanka, nadiren üzülür ama bu sabah yağmur resmen pikniğini mahvetti.'::text),
(314073,34897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ritkán szomorú, de ma reggel az eső lazán ... a pikniket.'::text,'tönkretette'::text,'tönkreteszi'::text,NULL::text,'Tesó, ritkán szomorú, de ma reggel az eső lazán tönkretette a pikniket.'::text),
(314076,34898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Update 14 Uhr: Gerade ... der traurige Mann in den Regen.'::text,'starrt'::text,'starrt'::text,'starrt'::text,'Update 14 Uhr: Gerade starrt der traurige Mann in den Regen.'::text),
(314080,34898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення о 14:00: сумний чоловік саме зараз ... на дощ.'::text,'дивиться'::text,'дивиться'::text,'дивиться'::text,'Оновлення о 14:00: сумний чоловік саме зараз дивиться на дощ.'::text),
(314079,34898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización de las 14:00: ahora mismo el hombre triste ... la lluvia.'::text,'está mirando'::text,'mira'::text,'está mirando'::text,'Actualización de las 14:00: ahora mismo el hombre triste está mirando la lluvia.'::text),
(314078,34898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Point de 14 h : en ce moment, l''homme triste ... la pluie.'::text,'est en train de fixer'::text,'fixe'::text,'est en train de fixer'::text,'Point de 14 h : en ce moment, l''homme triste est en train de fixer la pluie.'::text),
(314081,34898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 14.00 güncellemesi: şu an üzgün adam yağmura ...'::text,'bakıyor'::text,'bakar'::text,'bakıyor'::text,'Saat 14.00 güncellemesi: şu an üzgün adam yağmura bakıyor.'::text),
(314082,34898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frissítés 14:00: a szomorú férfi most épp az esőt ...'::text,'bámulja'::text,'bámulja'::text,'bámulja'::text,'Frissítés 14:00: a szomorú férfi most épp az esőt bámulja.'::text),
(314085,34899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist traurig, wenn es regnet, also ... es gerade draußen.'::text,'regnet'::text,'regnet'::text,NULL::text,'Er ist traurig, wenn es regnet, also regnet es gerade draußen.'::text),
(314089,34899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому сумно, коли йде дощ, тож саме зараз надворі ...'::text,'іде дощ'::text,'іде дощ'::text,NULL::text,'Йому сумно, коли йде дощ, тож саме зараз надворі іде дощ.'::text),
(314088,34899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se pone triste cuando llueve, así que ahora mismo ... fuera.'::text,'está lloviendo'::text,'llueve'::text,NULL::text,'Se pone triste cuando llueve, así que ahora mismo está lloviendo fuera.'::text),
(314087,34899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est triste quand il pleut, donc en ce moment, dehors, il ...'::text,'est en train de pleuvoir'::text,'pleut'::text,NULL::text,'Il est triste quand il pleut, donc en ce moment, dehors, il est en train de pleuvoir.'::text),
(314090,34899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağınca üzülür, bu yüzden şu an dışarıda yağmur ...'::text,'yağıyor'::text,'yağar'::text,NULL::text,'Yağmur yağınca üzülür, bu yüzden şu an dışarıda yağmur yağıyor.'::text),
(314091,34899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szomorú, ha esik, ezért most épp kint ... az eső.'::text,'esik'::text,'esik'::text,NULL::text,'Szomorú, ha esik, ezért most épp kint esik az eső.'::text),
(314103,34901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es regnet, also ... er zu Hause bleiben und traurig sein.'::text,'wird'::text,'wird'::text,'wird'::text,'Es regnet, also wird er zu Hause bleiben und traurig sein.'::text),
(314107,34901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Іде дощ, тож він ... залишитися вдома й сумувати.'::text,'збирається'::text,'збирається'::text,'збирається'::text,'Іде дощ, тож він збирається залишитися вдома й сумувати.'::text),
(314106,34901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está lloviendo, así que ... quedarse en casa y estar triste.'::text,'va a'::text,'va a'::text,'va a'::text,'Está lloviendo, así que va a quedarse en casa y estar triste.'::text),
(314105,34901,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pleut, donc il ... rester à la maison et être triste.'::text,'va'::text,'va'::text,'va'::text,'Il pleut, donc il va rester à la maison et être triste.'::text),
(314108,34901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağıyor, bu yüzden evde kalıp üzgün ...'::text,'olacak'::text,'olacak'::text,'olacak'::text,'Yağmur yağıyor, bu yüzden evde kalıp üzgün olacak.'::text),
(314109,34901,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esik az eső, ezért otthon ... maradni és szomorkodni.'::text,'fog'::text,'fog'::text,'fog'::text,'Esik az eső, ezért otthon fog maradni és szomorkodni.'::text),
(314112,34902,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir gesagt, es war der ... Tag seines Lebens.'::text,'traurigste'::text,'traurigste'::text,'traurigste'::text,'Girl, er hat mir gesagt, es war der traurigste Tag seines Lebens.'::text),
(314116,34902,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що це був ... день у його житті.'::text,'найсумніший'::text,'найсумніший'::text,'найсумніший'::text,'Подруго, він сказав мені, що це був найсумніший день у його житті.'::text),
