(314117,34902,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana hayatının ... günü olduğunu söyledi.'::text,'en üzücü'::text,'en üzücü'::text,'en üzücü'::text,'Kızım, bana hayatının en üzücü günü olduğunu söyledi.'::text),
