(314125,34903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... дивився у вікно.'::text,'сумно'::text,'сумний'::text,'смуток'::text,'Слухай, кажуть, він сумно дивився у вікно.'::text),
(314124,34903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer miró ... por la ventana.'::text,'tristemente'::text,'triste'::text,'tristeza'::text,'Oye, al parecer miró tristemente por la ventana.'::text),
