(298290,33144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O nein! Er ... einen neuen Haarschnitt und kein Zurück!'::text,'hat'::text,'haben'::text,'hat'::text,'O nein! Er hat einen neuen Haarschnitt und kein Zurück!'::text),
(298294,33144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О ні! Він ... нову стрижку, і шляху назад немає!'::text,'має'::text,'мати'::text,'має'::text,'О ні! Він має нову стрижку, і шляху назад немає!'::text),
(298293,33144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Oh, no! ¡... un corte de pelo nuevo y no hay vuelta atrás!'::text,'Tiene'::text,'Tienen'::text,'Tiene'::text,'¡Oh, no! ¡Tiene un corte de pelo nuevo y no hay vuelta atrás!'::text),
(298292,33144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh non ! Il ... une nouvelle coupe et pas de retour possible !'::text,'a'::text,'ont'::text,'a'::text,'Oh non ! Il a une nouvelle coupe et pas de retour possible !'::text),
(298295,33144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eyvah! Onun yeni bir saç kesimi ... ve geri dönüşü yok!'::text,'var'::text,'var'::text,'var'::text,'Eyvah! Onun yeni bir saç kesimi var ve geri dönüşü yok!'::text),
(298296,33144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jaj ne! Új frizurája ..., és nincs visszaút!'::text,'van'::text,'van'::text,'van'::text,'Jaj ne! Új frizurája van, és nincs visszaút!'::text),
(298299,33145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Haarschnitt, zwei rasierte ...! Sein Leben ändert sich für immer!'::text,'Seiten'::text,'Seite'::text,'Seiten'::text,'Ein Haarschnitt, zwei rasierte Seiten! Sein Leben ändert sich für immer!'::text),
(298303,33145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна стрижка, дві виголені ...! Його життя змінюється назавжди!'::text,'сторони'::text,'сторона'::text,'сторони'::text,'Одна стрижка, дві виголені сторони! Його життя змінюється назавжди!'::text),
(298302,33145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Un corte, dos ... rapados! ¡Su vida cambia para siempre!'::text,'lados'::text,'lado'::text,'lados'::text,'¡Un corte, dos lados rapados! ¡Su vida cambia para siempre!'::text),
(298301,33145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une coupe, deux ... rasés ! Sa vie change pour toujours !'::text,'côtés'::text,'côté'::text,'côtés'::text,'Une coupe, deux côtés rasés ! Sa vie change pour toujours !'::text),
