(298312,33146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Барбер малює стрижку в блокноті, а потім робить ... стрижку.'::text,''::text,NULL::text,NULL::text,'Барбер малює стрижку в блокноті, а потім робить стрижку.'::text),
