(298349,33150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe güncellemesi: saç kesimi 25 euro ve ... zaman alıyor.'::text,'az'::text,'az'::text,'çok'::text,'Bütçe güncellemesi: saç kesimi 25 euro ve az zaman alıyor.'::text),
(298350,33150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetési frissítés: a frizura 25 euróba kerül, és ... időt vesz igénybe.'::text,'kevés'::text,'kevés'::text,'sok'::text,'Költségvetési frissítés: a frizura 25 euróba kerül, és kevés időt vesz igénybe.'::text),
(309594,34400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziemlich beeindruckend: Du ... gerade einen riesigen Stapel wie ein Profi.'::text,'trägst'::text,'trägst'::text,'trägst'::text,'Ziemlich beeindruckend: Du trägst gerade einen riesigen Stapel wie ein Profi.'::text),
(309598,34400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить вражає: ти саме зараз ... величезну купу, як профі.'::text,'несеш'::text,'несеш'::text,'несеш'::text,'Досить вражає: ти саме зараз несеш величезну купу, як профі.'::text),
(309597,34400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante impresionante: ahora mismo ... una pila enorme como una pro.'::text,'estás llevando'::text,'llevas'::text,'estás llevando'::text,'Bastante impresionante: ahora mismo estás llevando una pila enorme como una pro.'::text),
(309596,34400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt impressionnant : tu ... une énorme pile comme une pro en ce moment.'::text,'es en train de porter'::text,'portes'::text,'es en train de porter'::text,'Plutôt impressionnant : tu es en train de porter une énorme pile comme une pro en ce moment.'::text),
(309599,34400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Epey etkileyici: şu an kocaman bir yığını profesyonel gibi ...'::text,'taşıyorsun'::text,'taşırsın'::text,'taşıyorsun'::text,'Epey etkileyici: şu an kocaman bir yığını profesyonel gibi taşıyorsun.'::text),
(309600,34400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég lenyűgöző: most épp úgy ... egy hatalmas kupacot, mint egy profi.'::text,'cipelsz'::text,'cipelsz'::text,'cipelsz'::text,'Elég lenyűgöző: most épp úgy cipelsz egy hatalmas kupacot, mint egy profi.'::text),
(309603,34401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise trägst du eine Tasche, aber heute ... du einen ganzen Stapel. Respekt.'::text,'trägst'::text,'trägst'::text,NULL::text,'Normalerweise trägst du eine Tasche, aber heute trägst du einen ganzen Stapel. Respekt.'::text),
(309607,34401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти носиш одну сумку, але сьогодні ти ... цілу купу. Респект.'::text,'несеш'::text,'несеш'::text,NULL::text,'Зазвичай ти носиш одну сумку, але сьогодні ти несеш цілу купу. Респект.'::text),
(309606,34401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente llevas una bolsa, pero hoy ... una pila entera. Chapó.'::text,'estás llevando'::text,'llevas'::text,NULL::text,'Normalmente llevas una bolsa, pero hoy estás llevando una pila entera. Chapó.'::text),
(309605,34401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu portes un sac, mais aujourd''hui tu ... toute une pile. Respect.'::text,'es en train de porter'::text,'portes'::text,NULL::text,'D''habitude tu portes un sac, mais aujourd''hui tu es en train de porter toute une pile. Respect.'::text),
(309608,34401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde tek çanta taşırsın ama bugün koca bir yığın ... Saygılar.'::text,'taşıyorsun'::text,'taşırsın'::text,NULL::text,'Genelde tek çanta taşırsın ama bugün koca bir yığın taşıyorsun Saygılar.'::text),
(309609,34401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában egy táskát viszel, de ma egy egész kupacot ... Respekt.'::text,'cipelsz'::text,'cipelsz'::text,NULL::text,'Általában egy táskát viszel, de ma egy egész kupacot cipelsz Respekt.'::text),
(309612,34402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für ein stabiler Stapel, klar. Er ... den ganzen Tag in ihren Armen bleiben.'::text,'wird'::text,'bleibt'::text,'blieb'::text,'Was für ein stabiler Stapel, klar. Er wird den ganzen Tag in ihren Armen bleiben.'::text),
(309616,34402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яка стабільна купа, звісно. Вона ... в її руках увесь день.'::text,'залишиться'::text,'залишається'::text,'залишалася'::text,'Яка стабільна купа, звісно. Вона залишиться в її руках увесь день.'::text),
(309615,34402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué pila tan estable, obviamente. ... en sus brazos todo el día.'::text,'Se quedará'::text,'Se queda'::text,'Se quedó'::text,'Qué pila tan estable, obviamente. Se quedará en sus brazos todo el día.'::text),
(309614,34402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelle pile stable, évidemment. Elle ... dans ses bras toute la journée.'::text,'restera'::text,'reste'::text,'est restée'::text,'Quelle pile stable, évidemment. Elle restera dans ses bras toute la journée.'::text),
(309617,34402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kadar sağlam bir yığın, belli. Bütün gün kollarında ...'::text,'kalacak'::text,'kalır'::text,'kaldı'::text,'Ne kadar sağlam bir yığın, belli. Bütün gün kollarında kalacak.'::text),
(309618,34402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda stabil kupac, nyilván. Egész nap a karjában ...'::text,'fog maradni'::text,'marad'::text,'maradt'::text,'Micsoda stabil kupac, nyilván. Egész nap a karjában fog maradni.'::text),
(309621,34403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stapel ist zu hoch, also ... er umfallen.'::text,'wird'::text,'wird'::text,'fällt'::text,'Der Stapel ist zu hoch, also wird er umfallen.'::text),
(309625,34403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Купа занадто висока, тож вона ...'::text,'збирається впасти'::text,'впаде'::text,'падає'::text,'Купа занадто висока, тож вона збирається впасти.'::text),
(309624,34403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pila es demasiado alta, así que ...'::text,'se va a caer'::text,'se caerá'::text,'se cae'::text,'La pila es demasiado alta, así que se va a caer.'::text),
(309623,34403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pile est trop haute, donc elle ...'::text,'va tomber'::text,'tombera'::text,'tombe'::text,'La pile est trop haute, donc elle va tomber.'::text),
(309626,34403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yığın çok yüksek, bu yüzden ...'::text,'devrilecek'::text,'devrilecek'::text,'devrilir'::text,'Yığın çok yüksek, bu yüzden devrilecek.'::text),
(309627,34403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kupac túl magas, ezért ...'::text,'fel fog borulni'::text,'fel fog borulni'::text,'felborul'::text,'A kupac túl magas, ezért fel fog borulni.'::text),
(309639,34405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quartalsbericht: Sie hat einen Haufen ... im Wert von 900 Euro gekauft.'::text,'Einkäufe'::text,'Einkäufe'::text,'einen Einkauf'::text,'Quartalsbericht: Sie hat einen Haufen Einkäufe im Wert von 900 Euro gekauft.'::text),
(309643,34405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Квартальний звіт: вона купила купу ... на 900 євро.'::text,'покупок'::text,'покупок'::text,'покупок'::text,'Квартальний звіт: вона купила купу покупок на 900 євро.'::text),
(309642,34405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe trimestral: compró un montón de ... por valor de 900 euros.'::text,'compras'::text,'compras'::text,'una compra'::text,'Informe trimestral: compró un montón de compras por valor de 900 euros.'::text),
(309641,34405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport trimestriel : elle a acheté une pile ... d''une valeur de 900 euros.'::text,'d''achats'::text,'d''achats'::text,'d''un achat'::text,'Rapport trimestriel : elle a acheté une pile d''achats d''une valeur de 900 euros.'::text),
(309644,34405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çeyrek raporu: 900 euro değerinde bir yığın ... aldı.'::text,'alışveriş'::text,'alışverişler'::text,'bir alışveriş'::text,'Çeyrek raporu: 900 euro değerinde bir yığın alışveriş aldı.'::text),
(309645,34405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negyedéves jelentés: egy halom ... vásárolt 900 euró értékben.'::text,'árut'::text,'árut'::text,'egy árut'::text,'Negyedéves jelentés: egy halom árut vásárolt 900 euró értékben.'::text),
(309648,34406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ... Kisten, deshalb ist da ein Stapel.'::text,'eine Menge'::text,'viel'::text,'ein bisschen'::text,'Sie hat eine Menge Kisten, deshalb ist da ein Stapel.'::text),
(309652,34406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї ... коробок, тому й є купа.'::text,'багато'::text,'багато'::text,'трохи'::text,'У неї багато коробок, тому й є купа.'::text),
(309651,34406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene ... cajas, así que por eso hay una pila.'::text,'un montón de'::text,'mucha'::text,'un poco de'::text,'Tiene un montón de cajas, así que por eso hay una pila.'::text),
(309650,34406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a ... cartons, donc c''est pour ça qu''il y a une pile.'::text,'plein de'::text,'beaucoup de'::text,'un peu de'::text,'Elle a plein de cartons, donc c''est pour ça qu''il y a une pile.'::text),
(309653,34406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kutusu var, işte bu yüzden bir yığın var.'::text,'Çok'::text,'Çok'::text,'Biraz'::text,'Çok kutusu var, işte bu yüzden bir yığın var.'::text),
(309654,34406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... doboza van, ezért van egy kupac.'::text,'Rengeteg'::text,'Sok'::text,'Egy kis'::text,'Rengeteg doboza van, ezért van egy kupac.'::text),
(309927,34437,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, dein kleines Flugzeug ... richtig Style.'::text,'hat'::text,'haben'::text,'hat'::text,'Ehrlich gesagt, dein kleines Flugzeug hat richtig Style.'::text),
(309931,34437,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, твій маленький літак ... класний стиль.'::text,'має'::text,'мати'::text,'має'::text,'Не буду брехати, твій маленький літак має класний стиль.'::text),
(309930,34437,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tu avioneta ... un estilazo.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'No te voy a mentir, tu avioneta tiene un estilazo.'::text),
(309929,34437,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, ton petit avion ... un style de ouf.'::text,'a'::text,'ont'::text,'a'::text,'Je vais pas mentir, ton petit avion a un style de ouf.'::text),
(309932,34437,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, küçük uçağının harika bir tarzı ...'::text,'var'::text,'var'::text,'var'::text,'Yalan yok, küçük uçağının harika bir tarzı var.'::text),
(309933,34437,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamuzok, a kis repülődnek szuper stílusa ...'::text,'van'::text,'van'::text,'van'::text,'Nem kamuzok, a kis repülődnek szuper stílusa van.'::text),
(309936,34438,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie du das Flugzeug so tief ..., ist echt smooth.'::text,'fliegst'::text,'fliegt'::text,'fliegend'::text,'Wie du das Flugzeug so tief fliegst, ist echt smooth.'::text),
(309940,34438,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Те, як ти ... цей літак так низько, — це стильно.'::text,'ведеш'::text,'веде'::text,'ведучи'::text,'Те, як ти ведеш цей літак так низько, — це стильно.'::text),
(309939,34438,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La forma en que ... ese avión tan bajo tiene mucho estilo.'::text,'pilotas'::text,'pilota'::text,'pilotando'::text,'La forma en que pilotas ese avión tan bajo tiene mucho estilo.'::text),
(309938,34438,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La façon dont tu ... cet avion si bas, c''est trop classe.'::text,'pilotes'::text,'pilote'::text,'pilotant'::text,'La façon dont tu pilotes cet avion si bas, c''est trop classe.'::text),
(309941,34438,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o uçağı öyle alçaktan ..., çok şık.'::text,'uçurursun'::text,'uçurur'::text,'uçurarak'::text,'Sen o uçağı öyle alçaktan uçurursun, çok şık.'::text),
(309942,34438,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy olyan alacsonyan ... azt a gépet, az nagyon elegáns.'::text,'vezeted'::text,'vezeti'::text,'vezető'::text,'Ahogy olyan alacsonyan vezeted azt a gépet, az nagyon elegáns.'::text),
(309945,34439,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine Flugzeug ... viele Kisten auf einmal tragen.'::text,'kann'::text,'kann'::text,'kann'::text,'Das kleine Flugzeug kann viele Kisten auf einmal tragen.'::text),
(309949,34439,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький літак ... перевезти багато ящиків одразу.'::text,'може'::text,'може'::text,'може'::text,'Маленький літак може перевезти багато ящиків одразу.'::text),
(309948,34439,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La avioneta ... llevar muchas cajas a la vez.'::text,'puede'::text,'puede'::text,'puede'::text,'La avioneta puede llevar muchas cajas a la vez.'::text),
(309947,34439,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit avion ... transporter beaucoup de caisses à la fois.'::text,'peut'::text,'peut'::text,'peut'::text,'Le petit avion peut transporter beaucoup de caisses à la fois.'::text),
(309950,34439,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük uçak aynı anda birçok sandık ...'::text,'taşıyabilir'::text,'taşıyabilir'::text,'taşıyabilir'::text,'Küçük uçak aynı anda birçok sandık taşıyabilir.'::text),
(309951,34439,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis repülő egyszerre sok ládát ... szállítani.'::text,'tud'::text,'tud'::text,'tud'::text,'A kis repülő egyszerre sok ládát tud szállítani.'::text),
(309972,34442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'„Ich ... das Flugzeug tiefer fliegen“, sagt sich der Pilot.'::text,'muss'::text,'muss'::text,'sollte'::text,'„Ich muss das Flugzeug tiefer fliegen“, sagt sich der Pilot.'::text),
(309976,34442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'«Я ... вести літак нижче», — каже собі пілот.'::text,'мушу'::text,'маю'::text,'мав би'::text,'«Я мушу вести літак нижче», — каже собі пілот.'::text),
(309975,34442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'«... volar más bajo con el avión», se dice el piloto.'::text,'Debo'::text,'Tengo que'::text,'Debería'::text,'«Debo volar más bajo con el avión», se dice el piloto.'::text),
(309974,34442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'« Je ... voler plus bas avec l''avion », se dit le pilote.'::text,'dois'::text,'dois'::text,'devrais'::text,'« Je dois voler plus bas avec l''avion », se dit le pilote.'::text),
(309977,34442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'“Uçağı daha alçaktan ...” diyor pilot kendi kendine.'::text,'uçurmalıyım'::text,'uçurmak zorundayım'::text,'uçurmalıyım'::text,'“Uçağı daha alçaktan uçurmalıyım” diyor pilot kendi kendine.'::text),
(309978,34442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'„Alacsonyabban ... vezetnem a gépet” – mondja magának a pilóta.'::text,'kell'::text,'kell'::text,'kellene'::text,'„Alacsonyabban kell vezetnem a gépet” – mondja magának a pilóta.'::text),
(309981,34443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kisten fallen schnell, also ... die Leute nicht unter dem Flugzeug stehen.'::text,'sollten'::text,'sollen'::text,'sollten'::text,'Die Kisten fallen schnell, also sollten die Leute nicht unter dem Flugzeug stehen.'::text),
(309985,34443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ящики падають швидко, тож люди не ... стояти під літаком.'::text,'мали б'::text,'будуть'::text,'мали б'::text,'Ящики падають швидко, тож люди не мали б стояти під літаком.'::text),
(309984,34443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las cajas caen rápido, así que la gente no ... quedarse debajo del avión.'::text,'debería'::text,'deberá'::text,'debería'::text,'Las cajas caen rápido, así que la gente no debería quedarse debajo del avión.'::text),
(309983,34443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les caisses tombent vite, donc les gens ne ... pas rester sous l''avion.'::text,'devraient'::text,'devront'::text,'devraient'::text,'Les caisses tombent vite, donc les gens ne devraient pas rester sous l''avion.'::text),
(309986,34443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandıklar hızlı düşüyor, bu yüzden insanlar uçağın altında ...'::text,'durmamalı'::text,'durmayacak'::text,'durmamalı'::text,'Sandıklar hızlı düşüyor, bu yüzden insanlar uçağın altında durmamalı.'::text),
(309987,34443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ládák gyorsan esnek, ezért az embereknek nem ... a repülő alatt állniuk.'::text,'kellene'::text,'kell'::text,'kellene'::text,'A ládák gyorsan esnek, ezért az embereknek nem kellene a repülő alatt állniuk.'::text),
(309990,34444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Weißt du was? Angeblich kam das Flugzeug zurück, ... eine Kiste nicht gereicht hat.'::text,'weil'::text,'aber'::text,'also'::text,'Weißt du was? Angeblich kam das Flugzeug zurück, weil eine Kiste nicht gereicht hat.'::text),
(309994,34444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви собі! Кажуть, літак повернувся, ... одного ящика було замало.'::text,'бо'::text,'але'::text,'тому'::text,'Уяви собі! Кажуть, літак повернувся, бо одного ящика було замало.'::text),
(309993,34444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Al parecer el avión volvió ... una caja no era suficiente.'::text,'porque'::text,'pero'::text,'así que'::text,'¿Sabes qué? Al parecer el avión volvió porque una caja no era suficiente.'::text),
